/* Ascentra client service layer. Replace LocalRepository with REST endpoints when campus services are available. */
const Core=typeof AscentraCore!=='undefined'?AscentraCore:(typeof require==='function'?require('./career-core'):window.AscentraCore);
const SKILLS=Core.SKILLS,roles=Core.ROLES,companies=Core.COMPANIES;
const defaults={student:{id:null,name:'',department:'',semester:null,cgpa:null,backlogs:0,target:null,secondary:[],skills:{},projects:[],internships:0,certifications:[],roadmap:{},customRoadmapActions:[],snapshots:[]},settings:{theme:'light',accent:'#c6f260',font:100,motion:true,contrast:100,density:'comfortable'},bookmarks:[],explored:[]};
const DEVICE_SETTING_KEYS=['theme','accent','font','motion','contrast','density'];
function deviceSettingsFrom(settings={}){return Object.fromEntries(DEVICE_SETTING_KEYS.filter(k=>Object.hasOwn(settings,k)).map(k=>[k,settings[k]]))}
const Store={
  key(id){return `ascentra:${id}`},
  deviceSettings(){let legacy={};try{legacy=deviceSettingsFrom(JSON.parse(localStorage.ascentra||'{}').settings||{})}catch{}try{return {...deviceSettingsFrom(defaults.settings),...legacy,...JSON.parse(localStorage.ascentraDeviceSettings||'{}')}}catch{return {...deviceSettingsFrom(defaults.settings),...legacy}}},
  get(id){try{if(id)return JSON.parse(localStorage.getItem(this.key(id))||'null');let legacy=JSON.parse(localStorage.ascentra||'{}');return {settings:{...this.deviceSettings(),...deviceSettingsFrom(legacy.settings||{})}}}catch{return {settings:this.deviceSettings()}}},
  saveDeviceSettings(settings={}){localStorage.ascentraDeviceSettings=JSON.stringify({...this.deviceSettings(),...deviceSettingsFrom(settings)});localStorage.removeItem('ascentra')},
  save(d,id=account?.id){this.saveDeviceSettings(d?.settings||{});if(id)localStorage.setItem(this.key(id),JSON.stringify(d))}
};
const AI_TRANSIENT_ERROR_TEXT='I’m having trouble connecting right now. Your profile tools are still available, and you can retry in a moment.';
function aiIsKnownFallbackText(text){let normalized=String(text||'').trim().replace(/^I'm/,'I’m');return normalized===AI_TRANSIENT_ERROR_TEXT}
function aiIsTransientErrorMessage(m){return !!m&&typeof m==='object'&&(m.transient===true||m.type==='error'||(m.error&&m.retry&&aiIsKnownFallbackText(m.content||m.text)))}
function sanitizeGuideHistory(history){return Array.isArray(history)?history.filter(m=>!aiIsTransientErrorMessage(m)&&['user','assistant'].includes(m?.role)):[]}
function sanitizeConversationState(data={}){let copy=structuredClone(data&&typeof data==='object'?data:{});if(Object.hasOwn(copy,'guideHistory'))copy.guideHistory=sanitizeGuideHistory(copy.guideHistory);return copy}
// Saved profiles evolve as features are added. Hydrate them before any screen reads
// nested values so users with older accounts can still sign in.
function migrateCustomRoadmapActions(student={}){
  let projects=Array.isArray(student.projects)?student.projects:[],custom=Array.isArray(student.customRoadmapActions)?student.customRoadmapActions:[],migrated=[];
  let kept=projects.filter((p,i)=>{
    let generated=p&&p.name==='Roadmap action'&&typeof p.detail==='string'&&Object.keys(p).every(k=>['name','detail'].includes(k));
    if(generated)migrated.push({id:`legacy-${i}-${Math.abs(p.detail.split('').reduce((n,ch)=>n+ch.charCodeAt(0),0))}`,text:p.detail,completed:false,createdAt:null,roleId:student.target||null,migratedFromProject:true});
    return !generated;
  });
  return {projects:kept,customRoadmapActions:[...custom,...migrated]};
}
function hydrateState(saved={}){let base=structuredClone(defaults),data=sanitizeConversationState(saved&&typeof saved==='object'?saved:{}),studentData=data.student||{},migrated=migrateCustomRoadmapActions(studentData);return {...base,...data,...(Object.hasOwn(data,'guideHistory')?{guideHistory:sanitizeGuideHistory(data.guideHistory)}:{}),student:{...base.student,...studentData,skills:{...base.student.skills,...(studentData.skills||{})},projects:migrated.projects,roadmap:{...base.student.roadmap,...(studentData.roadmap||{})},customRoadmapActions:migrated.customRoadmapActions,snapshots:Array.isArray(studentData.snapshots)?studentData.snapshots:base.student.snapshots},settings:{...base.settings,...(data.settings||{})},resume:{name:'No resume uploaded',text:'',skills:[],lastUploaded:null,stats:{},...(data.resume||{})},learning:{quizHistory:[],quizAdjustment:0,lastQuiz:null,...(data.learning||{})},onboarding:{step:0,messages:[],complete:false,...(data.onboarding||{})}}}
function hydrateAccountState(profile,user,{fresh=false}={}){let data=fresh?{}:(profile||Store.get(user?.id)||{}),next=hydrateState(data);next.settings={...next.settings,...Store.deviceSettings()};next.student.id=user?.id||next.student.id||null;if(user&&(fresh||!next.student.name))next.student.name=user.name||user.username||next.student.name||'';return next}
let state=hydrateState(Store.get()),view='dashboard',compare=[],isFirstLogin=false,lastSimulation=null,sidebarCollapsed=false,sidebarDrawerOpen=false;
try{sidebarCollapsed=localStorage.sidebarCollapsed==='true'}catch{}
const coreCtx=(student=state.student)=>({student,resume:state.resume,learning:state.learning});
const role=()=>Core.roleById(state.student.target,roles);
const skillVal=s=>state.student.skills[s]||0;
function roleScore(r=role(),student=state.student){return Core.roleScore(r,coreCtx(student))}
function eligibility(c){return Core.eligibility(c,role(),coreCtx())}
function relevantCompanies(r=role()){return Core.relevantCompanies(r,companies)}
function campus(r=role()){return Core.campus(r,coreCtx(),companies)}
function readiness(r=role(),student=state.student){return Core.readiness(r,coreCtx(student),companies)}
function gaps(r=role(),student=state.student){return Core.gaps(r,coreCtx(student),companies)}
const roadmapTitle=Core.roadmapTitle;
function roadmap(r=role()){return Core.roadmap(roleById(r),coreCtx(),companies)}
function nextAction(){let g=gaps()[0];return g?g:{name:'Maintain your momentum',need:100,current:100,impact:0}}
// The upload prompt is onboarding, not a dashboard reminder.  Keep the
// acknowledgement in the saved profile so re-renders (including theme changes)
// and later logins cannot show it again.
function shouldShowResumePrompt(){return isFirstLogin&&!state.resume.lastUploaded&&!state.onboarding.resumePromptShown}
const softSkills=['communication','teamwork','leadership','problem solving','adaptability','collaboration','time management'];
function parseResume(text,name){let t=String(text||''),find=a=>a.filter(s=>new RegExp('(^|[^a-z])'+s.replace(/[.+\\/]/g,'\\$&')+'([^a-z]|$)','i').test(t)),sections={};['projects','experience','internships','education','certifications','training','skills'].forEach(s=>sections[s]=new RegExp('(^|\\n)\\s*'+s,'i').test(t));let links=[...new Set((t.match(new RegExp('https?:\\/\\/[^\\s,;|]+|www\\.[^\\s,;|]+|(?:linkedin|github)\\.com\\/[^\\s,;|]+','gi'))||[]).map(x=>x.replace(/[.)]+$/,'')))],lines=t.split(/\\n+/).map(x=>x.trim()).filter(Boolean),identityName=lines.find(x=>/^[A-Za-z][A-Za-z .'-]{2,60}$/.test(x)&&!/(skills|education|project|experience|internship|certificate)/i.test(x))||'';let projects=lines.filter(x=>new RegExp('\\b(built|developed|created|implemented)\\b','i').test(x)).map(x=>x.slice(0,100)).slice(0,3);return {name,identityName,text:t.slice(0,30000),skills:find(SKILLS.filter(s=>s!=='Communication')),soft:find(softSkills),links,email:(t.match(/[\\w.+-]+@[\\w.-]+\\.[A-Za-z]{2,}/)||[])[0]||'',projects,sections,metrics:(t.match(/\\b\\d+(?:\\.\\d+)?\\s*(?:%|users?|members?|months?)\\b/gi)||[]).length,uploadedAt:Date.now(),version:(state.resume?.parsed?.version||0)+1}}
function academicYear(){let s=Number(state.student.semester);return s>=1&&s<=8?Math.ceil(s/2):null}
function resumeStats(){let d=state.resume.parsed;if(!d)return null;let req=Object.keys(role().req),matched=req.filter(s=>d.skills.includes(s)).length;return {skills:Math.round(d.skills.length/Math.max(SKILLS.length-1,1)*100),experience:Math.min(100,d.projects.length*30+(d.sections.experience?35:0)),compatibility:Math.round(matched/req.length*100),confidence:Math.min(100,35+(d.sections.skills?15:0)+(d.sections.projects?15:0)+(d.sections.education?15:0)+(d.text.length>700?20:0)),matched}}
function quizPage(){return ''}
function resumePage(){let stats=resumeStats(),r=role(),found=state.resume.skills||[];return layout(`<div class="page-head"><h1>Resume intelligence.</h1><p>Your uploaded evidence is translated into a live compatibility signal for ${r.name}.</p></div><section class="resume-workspace"><article class="resume-preview"><div class="resume-paper"><div class="resume-name">${esc(state.student.name)}</div><div class="resume-contact">${esc(state.resume.name)}</div><hr><h3>Profile focus</h3><p>${esc(r.name)} candidate with evidence mapped from the uploaded resume and saved profile.</p><h3>Detected skills</h3><p>${found.map(esc).join(' · ')||'Upload a resume to detect skills.'}</p><h3>Experience snapshot</h3><p>${state.student.projects.map(p=>esc(p.name)).join(' · ')||'No projects recorded yet.'}</p></div></article><aside class="resume-analysis"><div class="section-head"><h2>Live analysis</h2><span class="tag">FILLING NOW</span></div>${[['Resume skills',stats.skills],['Experience evidence',stats.experience],['Role compatibility',stats.compatibility],['Signal confidence',stats.confidence]].map(([n,v])=>`<div class="analysis-stat"><div class="gap-top"><span>${n}</span><strong class="count-up" data-value="${v}">0%</strong></div><div class="bar"><i style="width:0%" data-width="${v}%"></i></div></div>`).join('')}<button class="primary" id="resume-upload">Upload or replace resume</button><p class="sub">Last analyzed: ${state.resume.lastUploaded?new Date(state.resume.lastUploaded).toLocaleDateString():'Not yet'}</p><div class="reply">${resumeGuide()}</div></aside></section>`)}
function resumePage(){let d=state.resume.parsed,stats=resumeStats(),r=role(),year=academicYear();if(!d)return layout(`<div class="page-head"><h1>Resume intelligence.</h1><p>Upload a readable PDF or DOCX. Everything shown here will come from that file.</p></div><article class="resume-analysis"><h2>Build your evidence</h2><p>${year===1?'You’re early — build evidence, not a perfect resume.':'Upload your current resume for extracted sections and tailored next steps.'}</p><button class="primary" id="resume-upload">Upload resume</button></article>`);let missing=[];if(!d.sections.projects)missing.push([year>=4?'CRITICAL':year>=3?'IMPORTANT':'SUGGESTED','Add genuine projects relevant to '+r.name+'.']);if(!d.links.some(x=>/github/i.test(x)))missing.push(['SUGGESTED','Add GitHub if you have one, so reviewers can verify project work.']);if(!d.soft.length)missing.push(['SUGGESTED','If genuine, show collaboration or communication through a concrete contribution.']);if(year>=3&&!d.metrics)missing.push([year===4?'IMPORTANT':'SUGGESTED','Use measurable outcomes only where you can support them.']);let signals=[['Technical skills',d.skills.length?'Strong':'Needs attention',d.skills.length+' detected'],['Projects',d.sections.projects?'Strong':year===1?'Not relevant yet':'Needs attention',d.projects.length?'project evidence found':'no projects section'],['Online presence',d.links.length?'Strong':'Needs attention',d.links.length+' links found'],['Education',d.sections.education?'Strong':'Needs attention',d.sections.education?'section detected':'section not detected']];return layout(`<div class="page-head"><h1>Resume intelligence.</h1><p>Parsed evidence for ${r.name} — not a template or a prediction.</p></div><section class="resume-workspace"><article class="resume-preview"><div class="resume-paper"><div class="resume-name">${esc(d.identityName||state.student.name)}</div><div class="resume-contact">${esc(d.name)}</div><hr><h3>Detected technical skills</h3><p>${d.skills.map(esc).join(' · ')||'None found in the uploaded resume.'}</p><h3>Projects / experience</h3><p>${d.projects.map(esc).join(' · ')||'No project evidence detected.'}</p><h3>Contact and links</h3><p>${[d.email,...d.links].filter(Boolean).map(esc).join(' · ')||'No contact links detected.'}</p><h3>Resume signals</h3><div class="resume-signals">${signals.map(x=>`<div><strong>${esc(x[0])}</strong><span>${esc(x[1])}</span><small>${esc(x[2])}</small></div>`).join('')}</div></div></article><aside class="resume-analysis"><div class="section-head"><h2>Live analysis</h2><span class="tag">EVIDENCE-BASED</span></div>${[['Resume skills',stats.skills,`${d.skills.length} technical skills detected.`],['Experience evidence',stats.experience,`${d.projects.length} project items; ${d.sections.experience?'experience section found.':'no experience section found.'}`],['Role compatibility',stats.compatibility,`${stats.matched}/${Object.keys(r.req).length} target requirements appear.`],['Signal confidence',stats.confidence,'Calculated from parsed text and detected sections.']].map(([n,v,x])=>`<div class="analysis-stat"><div class="gap-top"><span>${n}</span><strong>${v}%</strong></div><div class="bar"><i style="width:${v}%"></i></div><small>${x}</small></div>`).join('')}<button class="primary" id="resume-upload">Upload or replace resume</button><p class="sub">Version ${d.version} · Last analyzed: ${new Date(d.uploadedAt).toLocaleDateString()}</p>${year>=3?'<p><a href="https://www.jobscan.co/resume-scanner" target="_blank" rel="noopener">External ATS Resume Check</a><br><small>Jobscan is separate from Ascentra’s analysis.</small></p>':''}<div class="reply"><strong>What to do next</strong>${missing.length?'<ol>'+missing.map(x=>`<li><b>${x[0]}:</b> ${esc(x[1])}</li>`).join('')+'</ol>':'<p>Your resume has the main evidence sections. Keep it current as you add work.</p>'}<small>${year?'Year '+year+' guidance. ':'Academic year unavailable. '}A generic format suits college-standard processes; use a specialized version when the company permits role tailoring.</small></div></aside></section>`) }
let account=null,appMode='loading';
function save(){let persistable=sanitizeConversationState(state);Store.save(persistable);if(account&&state.settings.rememberProfile!==false)fetch('/api/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(persistable)}).catch(()=>{})}function record(){state.student.snapshots.push({date:new Date().toLocaleDateString('en-IN',{month:'short',day:'numeric'}),score:readiness()});state.student.snapshots=state.student.snapshots.slice(-12);save()}
function esc(s){return String(s).replace(/[&<>]/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[x]))}function pill(status){return `<span class="pill ${status==='NEAR ELIGIBILITY'?'close':status==='NOT ELIGIBLE'?'no':''}">${status}</span>`}
function viewTitle(){return view==='quiz'?'Weekly Skill Check':view[0].toUpperCase()+view.slice(1)}
function viewHeading(){return view==='quiz'?'Weekly skill check.':viewTitle()}
function sidebarInitial(){let name=state.student.name||account?.username||account?.name||'Student';return esc(name.trim()[0]?.toUpperCase()||'S')}
function sidebarProfileText(){let dept=state.student.department||'Program not added',sem=state.student.semester?`Sem ${state.student.semester}`:'Semester not added';return `${esc(dept)} · ${esc(sem)}`}
function navIcon(id){let icons={dashboard:'M3 11.5 12 4l9 7.5M5 10v10h14V10M9 20v-6h6v6',roles:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18Zm3.5-12.5-2 5-5 2 2-5 5-2Z',companies:'M4 21h16M6 21V5h8v16M14 9h4v12M9 8h2M9 12h2M9 16h2',roadmap:'M5 18c3-6 11 0 14-6M5 18l3 .5M5 18l1.5-3M19 12l-3-.5M19 12l-1.5 3M7 7h.01M12 12h.01M17 7h.01',simulator:'M10 3v5l-4.5 8A3.5 3.5 0 0 0 8.5 21h7a3.5 3.5 0 0 0 3-5L14 8V3M9 3h6M8 16h8',constellation:'M12 12 6 7M12 12l6-5M12 12v7M6 7h.01M18 7h.01M12 19h.01M12 12h.01',profile:'M20 21a8 8 0 0 0-16 0M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z',settings:'M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7ZM19.4 15a1.7 1.7 0 0 0 .34 1.88l.04.04a2 2 0 1 1-2.83 2.83l-.04-.04A1.7 1.7 0 0 0 15 19.37a1.7 1.7 0 0 0-1 .63V20a2 2 0 1 1-4 0v-.06a1.7 1.7 0 0 0-1-.63 1.7 1.7 0 0 0-1.88.34l-.04.04a2 2 0 1 1-2.83-2.83l.04-.04A1.7 1.7 0 0 0 4.63 15a1.7 1.7 0 0 0-.63-1H4a2 2 0 1 1 0-4h.06a1.7 1.7 0 0 0 .63-1 1.7 1.7 0 0 0-.34-1.88l-.04-.04a2 2 0 1 1 2.83-2.83l.04.04A1.7 1.7 0 0 0 9 4.63a1.7 1.7 0 0 0 1-.63V4a2 2 0 1 1 4 0v.06a1.7 1.7 0 0 0 1 .63 1.7 1.7 0 0 0 1.88-.34l.04-.04a2 2 0 1 1 2.83 2.83l-.04.04A1.7 1.7 0 0 0 19.37 9c.24.36.45.58.63 1H20a2 2 0 1 1 0 4h-.06a1.7 1.7 0 0 0-.54 1Z',quiz:'M8 6h13M8 12h13M8 18h13M3.5 6l1 1 2-2M3.5 12l1 1 2-2M3.5 18l1 1 2-2'};return `<svg class="nav-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[id]||icons.dashboard}"></path></svg>`}
function sidebarArrowIcon(){return `<svg class="nav-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${sidebarCollapsed?'M9 18l6-6-6-6':'M15 18l-6-6 6-6'}"></path></svg>`}
function navButton([id,label]){return `<button class="nav ${view===id?'active':''}" data-nav="${id}" aria-label="${esc(label)}" title="${esc(label)}"><span class="nav-visual">${navIcon(id)}</span><span class="nav-label">${esc(label)}</span><span class="nav-tooltip" role="tooltip">${esc(label)}</span></button>`}
function layout(content){let navItems=[['dashboard','Dashboard'],['roles','Role explorer'],['companies','Companies'],['roadmap','Roadmap'],['simulator','What-if lab'],['constellation','Constellation'],['profile','My profile'],['settings','Settings'],['quiz','Weekly check']],collapsed=sidebarCollapsed?' sidebar-collapsed':'',drawer=sidebarDrawerOpen?' sidebar-open':'';return `<div class="shell${collapsed}${drawer}"><div class="sidebar-backdrop" data-sidebar-close></div><aside class="side" aria-label="Primary navigation"><div class="side-brand"><div class="brand-full"><div class="brand">ascent<i>ra</i></div><div class="tag">CAREER INTELLIGENCE</div></div><div class="brand-mark" aria-hidden="true">A</div></div><button type="button" class="sidebar-toggle" data-sidebar-toggle aria-label="${sidebarCollapsed?'Expand navigation':'Collapse navigation'}">${sidebarArrowIcon()}</button><nav>${navItems.map(navButton).join('')}</nav><button type="button" class="profile-mini" data-nav="profile" aria-label="Open profile for ${esc(state.student.name||'Student')}" title="${esc(state.student.name||'Student')}"><span class="profile-avatar-mini">${sidebarInitial()}</span><span class="profile-mini-text"><strong>${esc(state.student.name||'Student')}</strong><small>${sidebarProfileText()}</small></span><span class="nav-tooltip profile-tooltip" role="tooltip">${esc(state.student.name||'Student')}</span></button></aside><main class="main"><div class="top"><button type="button" class="mobile-menu" data-sidebar-menu aria-label="Open navigation">${navIcon('dashboard')}</button><div class="hello"><div class="tag">${view==='dashboard'?'YOUR PLACEMENT PULSE':'ASCENTRA / '+viewTitle()}</div><h1>${view==='dashboard'?'Build toward what matters.':viewHeading()}</h1><p>${view==='dashboard'?(state.student.target?`Targeting ${role().name} · live analysis from your profile`:'Choose a target role to activate career analysis.'):'All results recalculate from your saved profile.'}</p></div><div><button id="upload">↑ Resume</button> <button class="icon" id="theme" aria-label="Toggle dark mode">${state.settings.theme==='dark'?'☀':'◐'}</button></div></div>${content}</main></div>`}
function dashboard(){let r=role(),g=gaps(),cs=relevantCompanies(),ready=cs.filter(c=>eligibility(c)[0]==='ELIGIBLE'),close=cs.filter(c=>eligibility(c)[0]==='NEAR ELIGIBILITY'),a=nextAction();return layout(`<section class="grid metrics"><article class="card readiness"><div class="label">Placement readiness</div><div class="value">${readiness()}<small>/100</small></div><div class="sub">Preparedness, not placement probability</div></article><article class="card"><div class="label">Target role</div><div class="value" style="font-size:20px">${r.name}</div><button data-nav="roles">Change goal →</button></article><article class="card"><div class="label">Campus alignment</div><div class="value">${campus()}%</div><div class="sub">${cs.length} relevant campus opportunities</div></article><article class="card"><div class="label">Opportunity access</div><div class="value">${ready.length}<small> ready</small></div><div class="sub">${close.length} close · ${cs.length-ready.length-close.length} to build toward</div></article></section><section class="grid two"><div class="grid"><article class="card action"><div class="label">Next best action</div><h2>${a.name}</h2><p>Your largest weighted gap for ${r.name}, appearing across ${cs.length} relevant campus opportunities. Lifting it from ${a.current}% to ${a.need}% improves your score by an estimated ${Math.max(1,Math.round(a.impact*.16))} points.</p><button class="primary" data-view="roadmap">Start roadmap</button></article><article class="card"><div class="section-head"><h2>Priority skill gaps</h2><button data-view="profile">Edit skills</button></div>${g.slice(0,5).map(x=>`<div class="gap"><div class="gap-top"><span><strong>${x.name}</strong> · ${x.gap>=35?'Critical':x.gap>=20?'High':'Medium'}</span><span>${x.current}% → ${x.need}%</span></div><div class="bar"><i style="width:${x.current}%"></i></div></div>`).join('')||'<p class="sub">Your role requirements are covered.</p>'}</article></div><div class="grid"><article class="card"><div class="section-head"><h2>Company access</h2><button data-view="companies">Explore</button></div>${cs.slice(0,4).map(c=>{let e=eligibility(c);return `<div class="row"><span class="dot"></span><div class="row-main"><strong>${c.name}</strong><small>${c.industry} · ${c.pkg} LPA</small></div>${pill(e[0])}</div>`}).join('')}</article><article class="card guide"><div class="section-head"><h2>ASCENTRA AI</h2><span class="tag">GROUNDED</span></div><div class="reply" id="guide-reply">I’ve mapped your profile to ${r.name}. Ask about gaps, companies, or compare a role.</div><textarea id="guide-input" placeholder="Would improving DSA or React help me more?"></textarea><div class="chips"><button class="chip" data-guide="show my gaps">Show my gaps</button><button class="chip" data-guide="compare backend">Compare backend</button><button class="primary" id="guide-send">Ask Ascentra AI →</button></div></article></div></section>`)}
function rolesPage(){return layout(`<div class="page-head"><h1>Find a path with momentum.</h1><p>Role match combines normalized skills, project evidence, academic compatibility and campus demand.</p></div><div class="filters"><input id="role-search" placeholder="Search roles"><select id="role-cat"><option value="">All categories</option>${[...new Set(roles.map(r=>r.cat))].map(x=>`<option>${x}</option>`)}</select><button id="compare-open">Compare selected (${compare.length})</button></div><div class="cards" id="role-cards">${roleCards(roles)}</div>`)}
function roleCards(list){return list.map(r=>{let isTarget=r.id===state.student.target;return `<article class="card entity"><div class="label">${r.cat}</div><h3>${r.name}</h3><p>${r.desc}</p><div class="bar"><i style="width:${roleScore(r)}%"></i></div><small>${roleScore(r)}% profile alignment · ${campus(r)}% campus alignment</small><footer><button data-target="${r.id}" class="${isTarget?'lime':''}">${isTarget?'Primary goal':'Set goal'}</button><button data-compare="${r.id}">${compare.includes(r.id)?'✓ Selected':'Compare'}</button></footer></article>`}).join('')}
function companiesPage(){return layout(`<div class="page-head"><h1>Campus opportunity map.</h1><p>Eligibility reflects stored company rules and your live profile—never a prediction.</p></div><div class="filters"><input id="company-search" placeholder="Search company or industry"><select id="company-status"><option value="">All eligibility</option><option>ELIGIBLE</option><option>NEAR ELIGIBILITY</option><option>NOT ELIGIBLE</option></select><select id="company-role"><option value="">${role().name} opportunities</option>${roles.map(r=>`<option value="${r.id}">${r.name}</option>`).join('')}</select></div><div class="cards" id="company-cards">${companyCards(relevantCompanies())}</div>`)}
function companyCards(list){return list.map(c=>{let e=eligibility(c),rs=c.roleIds.map(id=>roles.find(r=>r.id===id).name).join(', ');return `<article class="card entity"><div class="section-head"><span class="label">${c.industry}</span>${pill(e[0])}</div><h3>${c.name}</h3><p>${rs}</p><div class="row"><div class="row-main"><strong>${c.pkg} LPA</strong><small>historical package</small></div><div><strong>≥ ${c.cgpa}</strong><small> CGPA</small></div></div><footer><small>${c.years.length} cycles · ${c.years.join(', ')}</small><button data-company="${c.id}">Details</button></footer></article>`}).join('')||'<article class="card"><p>No matching campus opportunities were found with these filters.</p></article>'}
function roadmapPage(){let phases=roadmap();let done=phases.flatMap(p=>p.items).filter(i=>i.done).length,total=phases.flatMap(p=>p.items).length;return layout(`<div class="page-head"><h1>Your ${role().name} roadmap.</h1><p>Priorities regenerate from your gaps. ${done}/${total} actions complete.</p></div><div class="bar" style="margin-bottom:22px"><i style="width:${total?done/total*100:0}%"></i></div><div class="cards">${phases.map(p=>`<article class="card"><div class="label">PRIORITY BAND</div><h2>${p.name}</h2>${p.items.map(i=>`<div class="row"><input type="checkbox" data-road="${i.id}" ${i.done?'checked':''}><div class="row-main"><strong>${i.name}</strong><small>Priority based on current evidence gap</small></div></div>`).join('')}</article>`).join('')}</div><article class="card" style="margin-top:16px"><h2>Add a personal action</h2><input id="custom-task" placeholder="e.g. Deploy my API project"><button id="add-task">Add</button><div id="custom-list"></div></article>`)}
function profilePage(){return layout(`<div class="page-head"><h1>Profile signal.</h1><p>Every adjustment persists locally and recalculates readiness, gaps and company access.</p></div><div class="grid two"><article class="card"><h2>Academic profile</h2><label>CGPA <input id="cgpa" type="number" min="0" max="10" step=".1" value="${state.student.cgpa}"></label><label>Backlogs <input id="backlogs" type="number" min="0" value="${state.student.backlogs}"></label><h3>Projects</h3>${state.student.projects.map(p=>`<div class="row"><div class="row-main"><strong>${esc(p.name)}</strong><small>${esc(p.detail)}</small></div></div>`).join('')}<button id="add-project">Add project</button></article><article class="card"><div class="section-head"><h2>Normalized skills</h2><button id="add-skill">Add skill</button></div><div id="skills-list">${Object.entries(state.student.skills).sort().map(([s,v])=>`<div class="skill-edit"><strong>${s}</strong><input data-skill="${s}" type="range" min="0" max="100" value="${v}"><span>${v}%</span></div>`).join('')}</div></article></div>`)}
function simulatorPageLegacy(){return simulatorPage()}
function constellationPage(){let r=role(),nodes=[['student',48,43,state.student.name],['role',48,14,r.name],...Object.keys(r.req).slice(0,6).map((s,i)=>['',12+i*15,75,s])];return layout(`<div class="page-head"><h1>Your career constellation.</h1><p>Click a skill node to inspect its live connection to roles and companies.</p></div><div class="constellation">${nodes.map(([cl,x,y,n])=>`<button class="node ${cl}" style="left:calc(${x}% - 37px);top:calc(${y}% - 37px)" data-node="${n}">${esc(n)}</button>`).join('')}</div>`)}
function settingsPage(){let s=state.settings;return layout(`<div class="page-head"><h1>Make Ascentra yours.</h1><p>Changes are persisted and applied immediately.</p></div><div class="grid two"><article class="card"><h2>Appearance</h2><div class="chips">${['light','dark','system'].map(x=>`<button data-set-theme="${x}" class="${s.theme===x?'lime':''}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><label>Accent color <input id="accent" type="color" value="${s.accent}"></label><label>Darkness / background contrast <input id="contrast" type="range" min="70" max="130" value="${s.contrast}"></label></article><article class="card"><h2>Accessibility & interface</h2><label>Font size <input id="font" type="range" min="85" max="125" value="${s.font}"></label><label><input id="motion" type="checkbox" ${s.motion?'checked':''}> Enable interface motion</label><label>Density <select id="density"><option ${s.density==='comfortable'?'selected':''}>comfortable</option><option ${s.density==='compact'?'selected':''}>compact</option></select></label><p class="sub">Reduced-motion preference also disables the radial transition.</p></article></div>`)}
function render(){applySettings();if(appMode==='login'||appMode==='register'||appMode==='forgot')return renderAuth();if(appMode==='welcome')return renderWelcome();if(appMode==='onboarding')return renderOnboarding();document.querySelector('#app').innerHTML=({dashboard,roles:rolesPage,companies:companiesPage,roadmap:roadmapPage,profile:profilePage,simulator:simulatorPage,constellation:constellationPage,settings:settingsPage,resume:resumePage,quiz:quizPage,academic:academicHealthPage,guide:guidePage}[view]||dashboard)();bind();if(view==='settings')accountControls();bindLearningViews();if(view==='dashboard'&&isFirstLogin&&!state.onboarding.academicYearKnown)showAcademicYearPrompt();else if(view==='dashboard'&&shouldShowResumePrompt())showResumeReminder()}
function bindLearningViews(){let nav=document.querySelector('.side nav');if(nav&&!nav.querySelector('[data-nav="quiz"]')){let quiz=document.createElement('button');quiz.className='nav';quiz.dataset.nav='quiz';quiz.textContent='▤ Weekly check';quiz.onclick=()=>{view='quiz';render()};nav.append(quiz)}document.querySelector('#resume-upload')?.addEventListener('click',()=>document.querySelector('#resume-input').click());document.querySelectorAll('.count-up').forEach(el=>{let value=+el.dataset.value,bar=el.parentElement.nextElementSibling.querySelector('i'),step=0,timer=setInterval(()=>{step=Math.min(value,step+4);el.textContent=step+'%';bar.style.width=step+'%';if(step>=value)clearInterval(timer)},45)})}
function enhanceResumeAnalysis(){let descriptions={'Resume skills':'Shows how much relevant technical skill evidence was detected in your uploaded resume.','Experience evidence':'Shows the strength of practical experience evidence found in your resume, such as projects, internships, training, or other relevant experience.','Role compatibility':'Shows how closely the skills and evidence found in your resume match the requirements of your selected target role.','Signal confidence':'Shows how confident the system is in its analysis based on the amount and clarity of information successfully extracted from your resume.'};document.querySelectorAll('.resume-analysis .analysis-stat').forEach(stat=>{let title=stat.querySelector('.gap-top span'),label=title?.textContent.trim(),description=descriptions[label];if(!description||stat.querySelector('.metric-info'))return;let info=document.createElement('span');info.className='metric-info';info.innerHTML=`<button type="button" aria-label="Information about ${esc(label)}">i</button><span class="metric-tooltip" role="tooltip">${esc(description)}</span>`;title.after(info)})}
new MutationObserver(()=>enhanceResumeAnalysis()).observe(document.querySelector('#app'),{childList:true,subtree:true});
function showResumeReminder(){
  if(document.querySelector('.resume-onboarding-modal'))return;
  // Mark it before displaying it. Theme changes re-render the dashboard, so
  // waiting until "Later" is clicked would allow the prompt to be recreated.
  state.onboarding.resumePromptShown=true;
  save();
  let m=document.createElement('div');
  m.className='modal resume-onboarding-modal';
  m.innerHTML='<div class="modal-box card"><div class="label">GET STARTED</div><h2>Add your resume or CV.</h2><p>Upload it once to give your career signal a more accurate starting point. You can replace it any time from Resume intelligence.</p><button class="primary" id="monthly-upload">Upload resume</button> <button class="close-modal">Later</button></div>';
  document.body.append(m);
  m.querySelector('#monthly-upload').onclick=()=>{m.remove();document.querySelector('#resume-input').click()};
  m.querySelector('.close-modal').onclick=()=>m.remove();
}
function showAcademicYearPrompt(){
  if(document.querySelector('.academic-year-modal'))return;
  let m=document.createElement('div');
  m.className='modal academic-year-modal';
  m.innerHTML='<div class="modal-box card"><div class="label">PERSONALIZE YOUR GUIDANCE</div><h2>What year are you in?</h2><p>Your year changes how Ascentra prioritizes resume, projects, internships, and placement preparation.</p><label>Current academic year<select id="academic-year"><option value="">Select your year</option><option value="1">Year 1</option><option value="2">Year 2</option><option value="3">Year 3</option><option value="4">Year 4</option></select></label><button class="primary" id="save-academic-year">Continue</button></div>';
  document.body.append(m);
  m.querySelector('#save-academic-year').onclick=()=>{let year=+m.querySelector('#academic-year').value;if(!year)return toast('Select your current academic year to continue.');state.student.semester=year*2;state.onboarding={...(state.onboarding||{}),academicYearKnown:true};isFirstLogin=false;save();m.remove();render()};
}
