function accountControls(){let w=document.createElement('article'),s=state.settings;w.className='card';w.style.marginTop='16px';w.innerHTML=`<h2>Account & data</h2><p class="sub">Login persistence is controlled by Remember me. These controls govern your career profile and ASCENTRA AI memory.</p><label><input id="remember-profile" type="checkbox" ${s.rememberProfile!==false?'checked':''}> Remember my career profile</label><label><input id="remember-conversations" type="checkbox" ${s.rememberConversations!==false?'checked':''}> Remember ASCENTRA AI conversations</label><div class="chips"><button id="view-data">View stored profile</button><button id="export-data">Download my data</button><button id="clear-conversations">Delete conversations</button><button id="rerun-onboarding">Re-run onboarding</button><button id="logout">Log out</button><button id="delete-account" class="primary">Delete account/data</button></div>`;document.querySelector('.main').append(w);document.querySelector('#remember-profile').onchange=e=>{state.settings.rememberProfile=e.target.checked;save()};document.querySelector('#remember-conversations').onchange=e=>{state.settings.rememberConversations=e.target.checked;save()};document.querySelector('#view-data').onclick=()=>modal(`<h2>Stored profile</h2><pre style="white-space:pre-wrap;font-size:11px">${esc(JSON.stringify(state.student,null,2))}</pre><button class="close-modal">Close</button>`);document.querySelector('#export-data').onclick=async()=>{let d=await (await fetch('/api/export')).json(),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='ascentra-profile.json';a.click()};document.querySelector('#clear-conversations').onclick=()=>{state.onboarding={...(state.onboarding||{}),messages:[]};save();toast('Conversations deleted.')};document.querySelector('#rerun-onboarding').onclick=()=>{state.onboarding={step:0,messages:[],complete:false};save();appMode='onboarding';render()};document.querySelector('#logout').onclick=async()=>{await fetch('/api/logout',{method:'POST'});account=null;appMode='login';render()};document.querySelector('#delete-account').onclick=async()=>{if(confirm('Delete account and stored profile?')){await fetch('/api/account',{method:'DELETE'});localStorage.removeItem('ascentra');account=null;appMode='login';render()}}}
