function openCompare(){if(compare.length<2)return toast('Select two or three roles to compare.');let rs=compare.map(id=>roles.find(r=>r.id===id));modal(`<h2>Role comparison</h2><div class="compare-grid">${rs.map(r=>`<div class="card"><div class="label">${r.cat}</div><h3>${r.name}</h3><p><strong>${roleScore(r)}%</strong> skill alignment</p><p><strong>${campus(r)}%</strong> campus alignment</p><p>${relevantCompanies(r).length} relevant companies</p><p>Top gap: ${gaps(r)[0]?.name||'None'}</p><button data-target="${r.id}">Set primary goal</button></div>`).join('')}</div><button class="close-modal">Close</button>`);document.querySelectorAll('.modal [data-target]').forEach(b=>b.onclick=()=>{state.student.target=b.dataset.target;record();closeModal();render()})}
function companyModal(c){let e=eligibility(c);modal(`<div class="label">${c.industry}</div><h2>${c.name}</h2>${pill(e[0])}<p>${e[1]}</p><hr><p><strong>Roles:</strong> ${c.roleIds.map(id=>roles.find(r=>r.id===id).name).join(', ')}</p><p><strong>Eligibility:</strong> CGPA ${c.cgpa}+ · Backlogs up to ${c.backlogs} · ${c.depts.join(', ')}</p><p><strong>Cycles:</strong> ${c.years.join(', ')} · typical package ${c.pkg} LPA</p><p><strong>Relevant skill signal:</strong> ${Object.keys(role().req).slice(0,5).join(', ')}</p><button class="close-modal">Close</button>`)}
function modal(content){let m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box card">${content}</div>`;document.body.append(m);m.querySelector('.close-modal')?.addEventListener('click',closeModal);m.addEventListener('click',e=>{if(e.target===m)closeModal()})}function closeModal(){document.querySelector('.modal')?.remove()}
