function switchTheme(e){let next=state.settings.theme==='dark'?'light':'dark';if(e.currentTarget?.dataset.setTheme)next=state.settings.theme;else state.settings.theme=next;save();let reduced=!state.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced&&e){let w=document.createElement('div'),size=Math.hypot(innerWidth,innerHeight)*2;w.className='wave';w.style.cssText+=`;right:0;top:0;width:${size}px;height:${size}px;background:${next==='dark'?'#0e1d1a':'#f4f5ef'}`;document.body.append(w);setTimeout(()=>{applySettings();w.remove();render()},1100)}else applySettings();if(reduced)render()}
async function extractResumeText(file){
  const ext=file.name.toLowerCase().split('.').pop();
  if(ext==='txt') return file.text();
  if(!['pdf','docx'].includes(ext)) throw new Error('Use a readable PDF, DOCX, or TXT resume.');
  const data=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('The selected file could not be opened.'));reader.readAsDataURL(file)});
  const response=await fetch('/api/resume/extract',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file.name,data})});
  const result=await response.json();
  if(!response.ok) throw new Error(result.error||'The resume could not be parsed.');
  return result.text;
}
function nameTokens(value){return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(x=>x.length>1)}
function validateResumeIdentity(profileName,resumeName){
  if(!resumeName||!resumeName.trim()) return {ok:true,reason:'unverified'};
  let profile=nameTokens(profileName),resume=nameTokens(resumeName);
  if(resume.length<2) return {ok:true,reason:'unverified'};
  if(!profile.length) return {ok:true,reason:'unverified'};
  const TRIVIAL=new Set(['mr','ms','mrs','dr','sr','jr']);
  let mProf=profile.filter(x=>!TRIVIAL.has(x)),mRes=resume.filter(x=>!TRIVIAL.has(x));
  if(mProf.some(x=>mRes.includes(x))) return {ok:true,reason:'verified'};
  let pFlat=mProf.join(''),rFlat=mRes.join('');
  if(pFlat.includes(rFlat)||rFlat.includes(pFlat)) return {ok:true,reason:'verified'};
  let initials=mRes.map(x=>x[0]);
  if(initials.length&&initials.every(i=>mProf.some(t=>t.startsWith(i)))) return {ok:true,reason:'verified'};
  return {ok:false,reason:'mismatch'};
}
function showResumeIdentityModal(reason){let unverified=reason==='unverified';modal(`<div class="label">RESUME CHECK</div><h2>${unverified?'Couldn’t verify the name on this resume.':'Resume doesn’t match your profile.'}</h2><p>${unverified?'Please upload a resume that clearly includes your name.':'This resume appears to belong to a different student. Please upload your own resume to continue.'}</p><button class="primary" id="identity-upload">${unverified?'Upload another resume':'Upload your resume'}</button>`);document.querySelector('#identity-upload').onclick=()=>{closeModal();document.querySelector('#resume-input').click()}}
document.querySelector('#resume-input').addEventListener('change',async e=>{let f=e.target.files[0];if(!f)return;if(f.size>5e6)return toast('Resume must be under 5 MB.');if(!/\.(txt|pdf|docx)$/i.test(f.name))return toast('Use TXT, PDF, or DOCX.');try{let text=await extractResumeText(f);if(text.trim().length<40)throw new Error('Little or no readable text was found.');let parsed=parseResume(text,f.name),identity=validateResumeIdentity(account?.name||state.student.name,parsed.identityName);if(!identity.ok){showResumeIdentityModal(identity.reason);return}state.resume={...(state.resume||{}),name:f.name,text:parsed.text,skills:parsed.skills,lastUploaded:parsed.uploadedAt,parsed,stats:{},versions:[...(state.resume?.versions||[]),{name:f.name,uploadedAt:parsed.uploadedAt,version:parsed.version}]};save();view='resume';render();toast(`Resume analyzed: ${parsed.skills.length} skills and ${parsed.projects.length} project signals detected.`)}catch(error){toast(`Resume could not be read: ${error.message} Upload another readable PDF or DOCX.`)}finally{e.target.value=''}});
function authSignalBars(){let heights=[34,46,58,42,70,52,38,64,78,48,60,72,44,54,82,66,36,50,68,76,40,62,56,74,45,59,84,53,37,69,80,47,63,55,73,41];return heights.map((h,i)=>`<i style="--h:${h}%;--d:${(i%9)*-220}ms;--dur:${2400+(i%6)*260}ms"></i>`).join('')}
function authShell(inner){let bars=authSignalBars();document.querySelector('#app').innerHTML=`<main class="auth"><section class="auth-brand"><div class="auth-brand-grid" aria-hidden="true"></div><header class="auth-brand-top"><div><div class="brand">ascent<i>ra</i></div><div class="tag">CAREER INTELLIGENCE</div></div><span class="auth-session">★ AI SESSION</span></header><div class="auth-hero-copy"><h1>Your career.<br><em>Intelligently guided.</em></h1><p>AI-powered career intelligence that understands<br>where you are, where you want to go,<br>and what it takes to get there.</p></div><div class="auth-orbit" role="img" aria-label="Career intelligence orbit connecting you with skills, role fit, roadmap, and opportunities"><div class="orbit-ring orbit-ring-a"></div><div class="orbit-ring orbit-ring-b"></div><div class="orbit-ring orbit-ring-c"></div><div class="orbit-center">YOU</div><div class="orbit-node orbit-skills"><strong>SKILLS</strong><span>Understand strengths</span></div><div class="orbit-node orbit-role"><strong>ROLE FIT</strong><span>Find roles you're meant for</span></div><div class="orbit-node orbit-roadmap"><strong>ROADMAP</strong><span>Build your path to success</span></div><div class="orbit-node orbit-opps"><strong>OPPORTUNITIES</strong><span>Discover the right opportunities</span></div><span class="orbit-dot orbit-dot-a"></span><span class="orbit-dot orbit-dot-b"></span><span class="orbit-dot orbit-dot-c"></span></div><div class="auth-data-stream" aria-hidden="true">${bars}</div><div class="auth-feature-strip" aria-label="ASCENTRA intelligence features"><div><span>↻</span><strong>Real-time insight</strong><small>Live data. Always updated.</small></div><div><span>✦</span><strong>Personalized guidance</strong><small>Made for your goals.</small></div><div><span>✓</span><strong>Actionable next steps</strong><small>Clear. Prioritized. Measurable.</small></div><div><span>◇</span><strong>Future-ready</strong><small>Stay ahead with AI.</small></div></div></section><section class="auth-panel">${inner}</section><button class="auth-theme" id="theme" aria-label="Toggle theme">${state.settings.theme==='dark'?'☀':'◐'}</button></main>`;document.querySelector('#theme').onclick=switchTheme}
function renderWelcome(){authShell(`<div class="auth-form"><div class="guide-id"><span>✦</span><div><strong>ASCENTRA AI</strong><small>your placement companion</small></div></div><h1>Hey, welcome to Ascentra.</h1><p>Before we build your placement roadmap, I want to understand where you are right now — what you know, what interests you, and where you want to go.</p><p>I’ll combine that with your resume and the placement opportunities at your university to make a path that is realistic for you.</p><button id="start-onboarding" class="primary">Let’s get started</button> <button id="explore-alone">I’ll explore on my own</button></div>`);document.querySelector('#start-onboarding').onclick=()=>{appMode='onboarding';render()};document.querySelector('#explore-alone').onclick=()=>{state.onboarding={...(state.onboarding||{}),complete:true};save();appMode='dashboard';render()}}
function renderAuth(){let title=appMode==='login'?'Welcome back.':appMode==='register'?'Start your career signal.':'Reset access';let fields=appMode==='register'?`<label class="auth-field"><span>Name</span><div class="auth-input-wrap"><span aria-hidden="true">◇</span><input id="auth-name" autocomplete="name"></div></label>`:'';let passwordAuto=appMode==='login'?'current':'new';let body=appMode==='forgot'?`<h1>${title}</h1><p>For this local development build, account recovery requires resetting the local data store. Passwords are intentionally never recoverable.</p><button data-auth="login">Back to sign in</button>`:`<h1>${title}</h1><p>${appMode==='login'?'Pick up exactly where you left off.':'A focused profile now. The intelligent part comes next.'}</p><form id="auth-form">${fields}<label class="auth-field"><span>Email</span><div class="auth-input-wrap"><span aria-hidden="true">@</span><input id="auth-email" type="email" autocomplete="email" required></div></label><label class="auth-field"><span>Password</span><div class="auth-input-wrap"><span aria-hidden="true">⌁</span><input id="auth-password" type="password" autocomplete="${passwordAuto}-password" minlength="8" required><button type="button" class="auth-password-toggle" id="auth-password-toggle" aria-label="Show password" aria-pressed="false">Show</button></div></label><label class="check"><input id="remember-login" type="checkbox"> Remember my login on this device</label><div id="auth-error" class="error" aria-live="polite"></div><button class="primary" type="submit">${appMode==='login'?'Sign in':'Create account'} →</button></form><div class="auth-links">${appMode==='login'?'<button data-auth="forgot">Forgot password?</button><button data-auth="register">Create account</button>':'<button data-auth="login">Already have an account? Sign in</button>'}</div><p class="auth-security">Secure sign-in to your ASCENTRA account.</p>`;authShell(`<div class="auth-form">${body}</div>`);document.querySelectorAll('[data-auth]').forEach(x=>x.onclick=()=>{appMode=x.dataset.auth;render()});document.querySelector('#auth-form')?.addEventListener('submit',submitAuth);document.querySelector('#auth-password-toggle')?.addEventListener('click',e=>{let input=document.querySelector('#auth-password'),show=input.type==='password';input.type=show?'text':'password';e.currentTarget.textContent=show?'Hide':'Show';e.currentTarget.setAttribute('aria-label',show?'Hide password':'Show password');e.currentTarget.setAttribute('aria-pressed',show?'true':'false')})}
async function submitAuth(e){e.preventDefault();let err=document.querySelector('#auth-error'),register=appMode==='register',payload={email:document.querySelector('#auth-email').value,password:document.querySelector('#auth-password').value,remember:document.querySelector('#remember-login').checked};if(register)payload.name=document.querySelector('#auth-name').value;err.textContent='';try{let endpoint=(location.protocol==='file:'?'http://localhost:4173':'')+'/api/'+(register?'register':'login'),r=await fetch(endpoint,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok){err.textContent=d.error;return}account=d.user;isFirstLogin=d.firstLogin===true;state=hydrateAccountState(d.profile,account,{fresh:register});compare=[];lastSimulation=null;window._ascentraLastPrompt='';save();appMode='dashboard';render()}catch(error){err.textContent=`Unable to connect to Ascentra. ${error.message||'Start the local server and try again.'}`}}
function guideSignals(ob){let e=ob.evidence||{},project=state.student.projects.length>0,skills=Object.values(state.student.skills).filter(x=>x>=45).length;return {careerDirection:Math.min(100,10+(e.goal||0)*30+(e.changeGoal||0)*12),skillConfidence:Math.min(100,8+(e.skills||0)*22+Math.min(skills,6)*5),knowledgeSignal:Math.min(100,5+(e.knowledge||0)*25),experience:Math.min(100,5+(e.experience||0)*25+(project?20:0)+state.student.internships*15)}}
function inferEvidence(text,ob){let t=text.toLowerCase(),e=ob.evidence||(ob.evidence={}),found=roles.find(r=>new RegExp(r.id==='fullstack'?'full[ -]?stack|web development':r.name.replace(/[/.]/g,'\\$&'),'i').test(text));if(found){state.student.target=found.id;e.goal=(e.goal||0)+1;if(/actually|instead|forget|change|more/.test(t))e.changeGoal=(e.changeGoal||0)+1}if(/built|made|project|intern|api|deployed|worked/.test(t)){e.experience=(e.experience||0)+1;state.student.projects.push({name:'Conversation evidence',detail:text.slice(0,140)})}if(/react|node|javascript|python|sql|dsa|api|backend|frontend|database/.test(t)){e.skills=(e.skills||0)+1;Object.keys(state.student.skills).forEach(s=>{if(t.includes(s.toLowerCase().replace('.js','')))state.student.skills[s]=Math.max(state.student.skills[s],45)})}if(/404|algorithm|complexity|database|because|means|knowledge/.test(t))e.knowledge=(e.knowledge||0)+1}
function guideContext(ob){let r=role();return {profile:{targetRole:r.name,skills:state.student.skills,projects:state.student.projects.slice(-4),internships:state.student.internships,signals:guideSignals(ob)},role:{name:r.name,description:r.desc,requirements:r.req,alignment:roleScore(r),gaps:gaps(r).slice(0,5)},campus:{alignment:campus(r),opportunities:relevantCompanies(r).map(c=>({name:c.name,roles:c.roleIds.map(id=>roles.find(r=>r.id===id).name),eligibility:eligibility(c)[0],requirements:{cgpa:c.cgpa,backlogs:c.backlogs,departments:c.depts}}))},dataNotice:'These are the only verified placement records available to the Guide.'}}
function animateProgressBars(prevSignals, newSignals) {
  document.querySelectorAll('.signal').forEach(el => {
    let key = el.dataset.signalKey;
    if (!key) return;
    let startVal = prevSignals[key] || 0;
    let targetVal = newSignals[key] || 0;
    let bar = el.querySelector('.bar i');
    let numEl = el.querySelector('strong');
    if (bar) bar.style.width = targetVal + '%';
    if (numEl) {
      let duration = 1200, startTime = null;
      function step(timestamp) {
        if (!startTime) startTime = timestamp;
        let progress = Math.min((timestamp - startTime) / duration, 1);
        let easeProgress = 1 - Math.pow(1 - progress, 3);
        let currentVal = Math.round(startVal + (targetVal - startVal) * easeProgress);
        numEl.textContent = currentVal + '%';
        if (progress < 1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }
  });
}
function typeWriterEffect(element, fullText, speed = 15, onComplete = null) {
  element.innerHTML = '';
  let i = 0;
  // Convert newlines to HTML breaks for proper rendering during typing
  let text = fullText;
  let timer = setInterval(() => {
    if (i < text.length) {
      let char = text.charAt(i);
      element.innerHTML += char === '\n' ? '<br>' : esc(char);
      i++;
      let box = document.querySelector('#messages');
      if (box) box.scrollTop = box.scrollHeight;
    } else {
      clearInterval(timer);
      element.innerHTML = esc(fullText).replace(/\n/g, '<br>');
      if (onComplete) onComplete();
    }
  }, speed);
}

function renderOnboarding(){let ob=state.onboarding||{messages:[],evidence:{},complete:false};state.onboarding=ob;if(!ob.signals)ob.signals={careerDirection:0,skillConfidence:0,knowledgeSignal:0,experience:0};let prevSignals=window._lastSignals||{...ob.signals},currentSignals=ob.signals;window._lastSignals={...currentSignals};if(!ob.messages.length)ob.messages.push({by:'ai',text:`Hey ${account?.name||state.student.name} — I’m your ASCENTRA AI. You don’t need to have everything figured out yet. Tell me what you’re currently thinking about becoming, or what feels uncertain.`});let items=[['careerDirection','Career direction',currentSignals.careerDirection,'How clearly we understand what you’re aiming for.'],['skillConfidence','Skill confidence',currentSignals.skillConfidence,'Evidence for your current skills.'],['knowledgeSignal','Knowledge signal',currentSignals.knowledgeSignal,'What the conversation tells us about your understanding.'],['experience','Experience',currentSignals.experience,'Project, internship, and practical evidence.']];authShell(`<div class="guide-workspace"><section class="onboard"><div class="guide-id"><span>✦</span><div><strong>ASCENTRA AI</strong><small>grounded in your saved profile and campus data</small></div></div><div class="messages" id="messages" aria-live="polite">${ob.messages.map(m=>`<article class="message ${m.by}"><p>${esc(m.text).replace(/\n/g,'<br>')}</p><time>${new Date(m.at||Date.now()).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></article>`).join('')}</div><div class="chips" aria-label="Suggested actions"><button data-prompt="Explain that more">Explain more</button><button data-prompt="Compare my current role with backend development">Compare roles</button><button data-prompt="I want to explore other roles">Explore roles</button><button data-prompt="I want to think about it for a bit">Let me think</button></div><label class="chat-entry"><span class="sr-only">Message ASCENTRA AI</span><textarea id="onboard-answer" rows="2" placeholder="Type your message…"></textarea><button class="primary" id="onboard-send">Send</button></label><button id="skip-onboarding">Build my roadmap when I’m ready</button></section><aside class="forming" aria-label="Profile confidence"><div class="tag">YOUR PROFILE IS FORMING <span title="These are confidence signals evaluated by AI from your conversation evidence.">ⓘ</span></div><h2>Evidence, not assumptions.</h2><p class="sub-text">These signals fill dynamically as the AI evaluates your conversation. Watch them build as you share more.</p>${items.map(([key,n,p,h])=>`<div class="signal" data-signal-key="${key}"><div class="gap-top"><span>${n}</span><strong>${prevSignals[key]||0}%</strong></div><div class="bar" title="${h}"><i style="width:${prevSignals[key]||0}%"></i></div><small>${h}</small></div>`).join('')}</aside></div>`);let box=document.querySelector('#messages');box.scrollTop=box.scrollHeight;setTimeout(()=>animateProgressBars(prevSignals,currentSignals),50);let send=async text=>{text=(text||document.querySelector('#onboard-answer').value).trim();if(!text)return;let inputEl=document.querySelector('#onboard-answer');if(inputEl)inputEl.value='';inferEvidence(text,ob);ob.messages.push({by:'user',text,at:Date.now()});save();renderOnboarding();let messages=document.querySelector('#messages');let thinkingId='thinking-'+Date.now();messages.insertAdjacentHTML('beforeend',`<article class="message ai thinking" id="${thinkingId}"><p>ASCENTRA AI is thinking <i></i><i></i><i></i></p></article>`);messages.scrollTop=messages.scrollHeight;try{let response=await fetch(apiUrl('/api/ai/career-guide/chat'),{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,history:ob.messages.map(m=>({role:m.by==='user'?'user':'assistant',content:m.text}))})}),data=await response.json();let thinkingEl=document.querySelector('#'+thinkingId);if(!response.ok)throw new Error(data.detail||data.error||'Response failed');let fullAnswer=data.answer;ob.messages.push({by:'ai',text:fullAnswer,at:Date.now()});if(data.evaluations){let ev=data.evaluations;if(ev.careerDirectionDelta)ob.signals.careerDirection=Math.min(100,(ob.signals.careerDirection||0)+ev.careerDirectionDelta);if(ev.skillConfidenceDelta)ob.signals.skillConfidence=Math.min(100,(ob.signals.skillConfidence||0)+ev.skillConfidenceDelta);if(ev.knowledgeSignalDelta)ob.signals.knowledgeSignal=Math.min(100,(ob.signals.knowledgeSignal||0)+ev.knowledgeSignalDelta);if(ev.experienceDelta)ob.signals.experience=Math.min(100,(ob.signals.experience||0)+ev.experienceDelta)}if(data.detectedTargetRole){let found=roles.find(r=>r.id===data.detectedTargetRole||r.name.toLowerCase().includes(String(data.detectedTargetRole).toLowerCase()));if(found)state.student.target=found.id}save();if(thinkingEl){thinkingEl.classList.remove('thinking');let pEl=thinkingEl.querySelector('p');typeWriterEffect(pEl,fullAnswer,12,()=>{save();renderOnboarding()});}else{renderOnboarding();}}catch(error){let thinkingEl=document.querySelector('#'+thinkingId);let errText=error.message||'ASCENTRA AI is temporarily unavailable. Please try again.';ob.messages.push({by:'ai',text:errText,at:Date.now(),error:true});save();if(thinkingEl){thinkingEl.classList.remove('thinking');thinkingEl.innerHTML=`<p>${esc(errText)}</p>`;}else{renderOnboarding();}}};document.querySelector('#onboard-send').onclick=()=>send();document.querySelector('#onboard-answer').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>send(b.dataset.prompt));document.querySelector('#skip-onboarding').onclick=()=>{ob.complete=true;record();save();appMode='dashboard';render()}}
