profilePage=function(){let s=state.student,parsed=state.resume?.parsed,guideState=state.profileGuide||{messages:[]},reported=Object.entries(s.skills||{}),resumeSkills=(parsed?.skills||[]).filter(x=>!Object.keys(s.skills||{}).some(y=>y.toLowerCase()===x.toLowerCase()));return layout(`<div class="page-head"><h1>Career profile.</h1><p>${s.target?'Your saved evidence and career direction.':'Your career profile is still forming.'}</p></div><section class="grid two profile-identity"><article class="card"><div class="section-head"><h2>Personal & academic profile</h2><span class="tag">${s.target?'TARGET SELECTED':'EXPLORING'}</span></div><label>Full name<input id="profile-fullname" value="${esc(s.name||account?.name||'')}" placeholder="Your full name"></label><label>University / college<input id="profile-university" value="${esc(s.university||'')}" placeholder="Add your university"></label><label>Degree<input id="profile-degree" value="${esc(s.degree||'')}" placeholder="e.g. B.Tech"></label><label>Department<input id="profile-department" value="${esc(s.department||'')}" placeholder="e.g. CSE"></label><label>Semester<input id="profile-semester" type="number" min="1" max="8" value="${esc(s.semester||'')}"></label><label>CGPA<input id="profile-cgpa" type="number" min="0" max="10" step=".01" value="${esc(s.cgpa??'')}"></label><button class="primary" id="save-profile-details">Save profile</button></article><article class="card"><div class="label">CAREER DIRECTION</div><h2>${s.target?esc(role().name):'Your direction is still forming.'}</h2><p>${s.target?'This selection updates role matching and skill-gap guidance.':'Explore roles or tell ASCENTRA AI what you enjoy building and solving.'}</p><button id="profile-explore-roles">Explore career directions</button><div class="profile-actions"><button data-profile-action="skills">Analyze my skills</button><button data-profile-action="gap">Find my biggest skill gap</button><button data-profile-action="roadmap">Build my roadmap</button></div></article></section><section class="grid two"><article class="card"><div class="section-head"><h2>Technical skills</h2><button id="profile-add-skill">Add skill</button></div>${reported.length?reported.map(([k,v])=>`<div class="row"><div class="row-main"><strong>${esc(k)}</strong><small>Added by you · ${esc(String(v))}% profile score</small></div><button data-remove-skill="${esc(k)}">Remove</button></div>`).join(''):'<p class="sub">No student-reported skills yet.</p>'}${resumeSkills.length?`<h3>Detected from resume</h3>${resumeSkills.map(x=>`<div class="row"><div class="row-main"><strong>${esc(x)}</strong><small>Resume evidence</small></div></div>`).join('')}`:''}</article><article class="card"><div class="section-head"><h2>Evidence</h2><button id="profile-resume-upload">Upload / Replace Resume</button></div><p>${parsed?`${parsed.projects?.length||0} project signals · ${parsed.links?.length||0} verified links from your resume.`:'Add projects, experience, or a validated resume as you build evidence.'}</p><div class="profile-actions"><button data-profile-action="resume">Improve my resume</button><button data-profile-action="roles">Explore matching roles</button></div></article></section><section class="card profile-guide"><div class="section-head"><div><div class="label">ASCENTRA AI</div><h2>Ask about your actual career evidence.</h2></div><span class="tag">READY</span></div><div class="profile-guide-messages">${guideState.messages.length?guideState.messages.map(m=>`<p class="${m.by}"><strong>${m.by==='user'?'You':'ASCENTRA AI'}:</strong> ${esc(m.text)}</p>`).join(''):'<p class="sub">What kinds of things do you enjoy building or solving?</p>'}</div><label><span class="sr-only">Ask Ascentra AI</span><textarea id="profile-guide-input" rows="2" placeholder="What should I work on next?"></textarea></label><button class="primary" id="profile-guide-send">Ask Ascentra AI</button></section>`)};
