document.addEventListener('click',e=>{if(e.target.closest('.profile-mini')){view='profile';render()}if(e.target.closest('#dashboard-resume-action')){resumeUploadWorkspace=true;view='resume';render()}if(e.target.closest('#resume-back')){resumeUploadWorkspace=false;view='dashboard';render()}if(e.target.closest('#workspace-browse'))document.querySelector('#resume-input').click();if(e.target.closest('#dashboard-start-guide')){appMode='onboarding';render()}});
document.addEventListener('dragover',e=>{if(e.target.closest('#upload-drop'))e.preventDefault()});
document.addEventListener('click',async e=>{if(e.target.closest('#profile-resume-upload')||e.target.closest('[data-profile-action="resume"]')){resumeUploadWorkspace=true;view='resume';render();return}if(e.target.closest('[data-profile-action="roles"]')){view='roles';render();return}let photo=e.target.closest('[data-profile-photo]');if(photo){if(photo.dataset.profilePhoto==='upload')document.querySelector('#profile-photo-input')?.click();else{delete state.student.photoData;save();toast('Profile photo removed.');render()}return}let ai=e.target.closest('[data-profile-ai]');if(ai){view='dashboard';render();let input=document.querySelector('#guide-input');if(input){input.value=ai.dataset.profileAi;guide()}return}if(e.target.closest('#profile-add-skill')){let skill=prompt('Skill name:'),level=skill&&prompt('Self-assessment: Beginner, Familiar, Intermediate, or Advanced');if(skill){let known=SKILLS.find(s=>s.toLowerCase()===skill.toLowerCase())||skill.trim(),levels={beginner:25,familiar:45,intermediate:65,advanced:85};state.student.skills[known]=levels[String(level||'').toLowerCase()]||45;save();toast(`${known} added as self-reported evidence.`);render()}return}let remove=e.target.closest('[data-remove-skill]');if(remove){delete state.student.skills[remove.dataset.removeSkill];save();toast('Skill removed.');render();return}if(e.target.closest('#save-profile-details')){for(let [id,key,asNumber] of [['profile-fullname','name'],['profile-university','university'],['profile-degree','degree'],['profile-department','department'],['profile-semester','semester',true],['profile-cgpa','cgpa',true]]){let field=document.querySelector('#'+id);if(!field)continue;state.student[key]=asNumber?(field.value===''?null:+field.value):field.value.trim()}save();try{await fetch(apiUrl('/api/profile/update'),{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(state.student)});toast('Profile saved.')}catch{toast('Saved locally; server sync will retry.')}render();return}});
document.addEventListener('change',e=>{if(e.target.id!=='profile-photo-input')return;let file=e.target.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){toast('Use a JPG, PNG, or WebP image.');e.target.value='';return}if(file.size>4*1024*1024){toast('Profile photo must be under 4 MB.');e.target.value='';return}let reader=new FileReader();reader.onload=()=>{state.student.photoData=String(reader.result||'');save();toast('Profile photo updated.');render()};reader.onerror=()=>toast('Photo could not be read.');reader.readAsDataURL(file)},true);
document.addEventListener('drop',e=>{let drop=e.target.closest('#upload-drop');if(!drop)return;e.preventDefault();let file=e.dataTransfer?.files?.[0];if(!file)return;let transfer=new DataTransfer();transfer.items.add(file);let input=document.querySelector('#resume-input');input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}))});
document.querySelector('#resume-input').addEventListener('change',()=>{let status=document.querySelector('#upload-status');if(status)status.textContent='Validating and parsing your resume…'},{capture:true});
new MutationObserver(()=>applyResumeUploadLocation()).observe(document.querySelector('#app'),{childList:true,subtree:true});
function academicRiskDefaults(){return {semester:state.student.semester||'',attendance_percentage:'',ca1_score:'',ca2_score:'',ca3_score:'',mid_term_score:'',previous_semester_tgpa:'',academic_trend:'Stable',...(state.student.academicRiskInput||{})}}
function best2Average(input){let scores=[+input.ca1_score,+input.ca2_score,+input.ca3_score].filter(Number.isFinite).sort((a,b)=>b-a);return scores.length===3?Math.round(((scores[0]+scores[1])/2)*10)/10:null}
function riskPercent(result){return result?.risk_probability==null?'--':Math.round(result.risk_probability*100)+'%'}
function factorList(items){return (items||[]).slice(0,5).map(x=>`<li><strong>${esc(x.feature)}</strong><span>${esc(x.value??'unavailable')}</span><small>${esc(x.direction==='reduces_risk'?'Working in your favor':'Needs attention')}</small></li>`).join('')||'<li><span>No factors returned yet.</span></li>'}
function interventionList(items){return (items||[]).slice(0,3).map(x=>`<li><strong>${esc(x.risk_factor||'Risk factor')}</strong><span>${esc(x.recommendation||'Review with advisor.')}</span></li>`).join('')||'<li><span>No interventions returned yet.</span></li>'}
function academicRiskPanel(){let input=academicRiskDefaults(),result=state.student.academicRiskResult?.result||state.student.academicRiskResult,error=state.student.academicRiskError,best=best2Average(input),sem1=String(input.semester)==='1';return `<section class="academic-risk card" id="academic-risk"><div class="section-head"><div><div class="label">ACADEMIC RISK</div><h2>Early-warning check</h2></div><span class="tag">${result?esc(result.risk_level||'READY'):'MODULE A'}</span></div><form id="academic-risk-form" class="academic-risk-form"><label>Semester<input name="semester" type="number" min="1" max="8" value="${esc(input.semester)}" required></label><label>Attendance %<input name="attendance_percentage" type="number" min="0" max="100" step=".1" value="${esc(input.attendance_percentage)}" required></label><label>CA1 score<input name="ca1_score" type="number" min="0" max="30" step=".1" value="${esc(input.ca1_score)}" required></label><label>CA2 score<input name="ca2_score" type="number" min="0" max="30" step=".1" value="${esc(input.ca2_score)}" required></label><label>CA3 score<input name="ca3_score" type="number" min="0" max="30" step=".1" value="${esc(input.ca3_score)}" required></label><label>Mid-term score<input name="mid_term_score" type="number" min="0" max="30" step=".1" value="${esc(input.mid_term_score)}" required></label><label>Previous TGPA<input name="previous_semester_tgpa" type="number" min="0" max="10" step=".01" value="${esc(sem1?'':input.previous_semester_tgpa)}" ${sem1?'disabled':''} placeholder="${sem1?'Unavailable for semester 1':''}"></label><label>Academic trend<select name="academic_trend"><option ${input.academic_trend==='Declining'?'selected':''}>Declining</option><option ${input.academic_trend==='Stable'?'selected':''}>Stable</option><option ${input.academic_trend==='Improving'?'selected':''}>Improving</option></select></label><div class="academic-risk-actions"><span>Best 2 CA average: <strong id="best2-preview">${best??'--'}</strong></span><button class="primary" type="submit">Check academic risk</button></div></form>${error?`<p class="risk-error">${esc(error)}</p>`:''}${result?`<div class="academic-risk-result"><div class="risk-summary"><div><span>Risk probability</span><strong>${riskPercent(result)}</strong></div><div><span>Risk level</span><strong>${esc(result.risk_level)}</strong></div><div><span>Decision</span><strong>${esc(result.decision)}</strong></div><div><span>Trend</span><strong>${esc(input.academic_trend)}</strong></div></div><div class="risk-columns"><div><h3>Key risk factors</h3><ul>${factorList(result.risk_factors)}</ul></div><div><h3>Protective factors</h3><ul>${factorList(result.protective_factors)}</ul></div></div><div class="risk-interventions"><h3>Recommended interventions</h3><ol>${interventionList(result.interventions)}</ol></div></div>`:''}</section>`}
const dashboardBeforeAcademicRisk=dashboard;
dashboard=function(){return dashboardBeforeAcademicRisk().replace('</main>',academicRiskPanel()+'</main>')}
function readAcademicRiskForm(form){let data=Object.fromEntries(new FormData(form).entries());let semester=Number(data.semester),payload={student_id:state.student.id||account?.id||null,semester,attendance_percentage:Number(data.attendance_percentage),ca1_score:Number(data.ca1_score),ca2_score:Number(data.ca2_score),ca3_score:Number(data.ca3_score),mid_term_score:Number(data.mid_term_score),previous_semester_tgpa:semester===1?null:(data.previous_semester_tgpa===''?null:Number(data.previous_semester_tgpa)),academic_trend:data.academic_trend};payload.best_2_ca_average=best2Average(payload);return payload}
document.addEventListener('input',e=>{let form=e.target.closest?.('#academic-risk-form');if(!form)return;let payload=readAcademicRiskForm(form),preview=document.querySelector('#best2-preview');if(preview)preview.textContent=payload.best_2_ca_average??'--';let prev=form.elements.previous_semester_tgpa;if(prev){prev.disabled=payload.semester===1;if(payload.semester===1)prev.value=''}})
document.addEventListener('submit',async e=>{if(e.target.id!=='academic-risk-form')return;e.preventDefault();let payload=readAcademicRiskForm(e.target);state.student.academicRiskInput=payload;state.student.academicRiskError='';state.student.academicRiskResult=null;save();let button=e.target.querySelector('button[type="submit"]');if(button)button.textContent='Checking...';try{let response=await fetch(apiUrl('/api/academic-risk'),{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.error||data.detail||'Academic Risk service could not evaluate this student.');state.student.academicRiskResult=data.result||data;state.student.academicRiskInput=data.input||payload;toast('Academic risk evaluated.')}catch(error){state.student.academicRiskError=error.message||'Academic Risk service is unavailable.';toast(state.student.academicRiskError)}save();try{await fetch(apiUrl('/api/profile/update'),{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({academicRiskInput:state.student.academicRiskInput,academicRiskResult:state.student.academicRiskResult})})}catch{}render()})
const fmtNumber=(value,digits=1)=>Number.isFinite(Number(value))?Number(value).toFixed(digits).replace(/\.0$/,''):'unavailable';
const featureLabels={semester:'Semester',attendance_percentage:'Attendance',ca1_score:'CA1 score',ca2_score:'CA2 score',ca3_score:'CA3 score',best_2_ca_average:'Best 2 CA average',mid_term_score:'Mid-term score',previous_semester_tgpa:'Previous semester TGPA',academic_trend:'Academic trend',ca_average:'CA average',ca_improvement:'CA performance change',ca_consistency:'CA consistency',attendance_best2_interaction:'Attendance x best 2 CA',attendance_midterm_interaction:'Attendance x mid-term',tgpa_best2_interaction:'Previous TGPA x CA performance',previous_tgpa_available:'Previous TGPA availability'};
function featureLabel(name){return featureLabels[name]||String(name||'Model signal').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase())}
function featureValue(name,value){if(value==null||value==='')return 'Unavailable';if(String(name).includes('percentage'))return fmtNumber(value,1)+'%';if(String(name).includes('tgpa'))return fmtNumber(value,2);if(typeof value==='number')return fmtNumber(value,2);return String(value)}
factorList=function(items){return (items||[]).slice(0,5).map(x=>`<li><strong>${esc(featureLabel(x.feature))}</strong><span>${esc(featureValue(x.feature,x.value))}</span><small>${esc(x.direction==='reduces_risk'?'Working in your favor':'Needs attention')}</small></li>`).join('')||'<li><span>No factors returned yet.</span></li>'}
function info(label,text){return `<span class="metric-info"><button type="button" aria-label="Information about ${esc(label)}">i</button><span class="metric-tooltip" role="tooltip">${esc(text)}</span></span>`}
function readinessParts(r=role(),student=state.student){let projectMatches=student.projects.filter(p=>Object.keys(r.req).some(s=>String(p.detail||'').toLowerCase().includes(s.toLowerCase().replace('.js','')))).length,parts={skillAlignment:roleScore(r,student),resumeProjectEvidence:Math.min(100,student.projects.length*35+projectMatches*20),academicProfile:Math.max(0,Math.min(100,((student.cgpa||0)/8)*100-((student.backlogs||0)*15))),experienceEvidence:Math.min(100,(student.internships||0)*55+(student.certifications||[]).length*15),campusOpportunityAlignment:campus(r)};parts.total=Math.round(parts.skillAlignment*.5+parts.resumeProjectEvidence*.18+parts.academicProfile*.17+parts.experienceEvidence*.08+parts.campusOpportunityAlignment*.07);return parts}
function readinessExplain(){let p=readinessParts(),rows=[['Skill alignment',p.skillAlignment,'Selected-role coverage from the centralized skill evidence engine.'],['Resume/project evidence',p.resumeProjectEvidence,'Project count and role-relevant project descriptions saved in your profile.'],['Academic profile',p.academicProfile,'CGPA and backlog readiness for campus eligibility rules.'],['Experience evidence',p.experienceEvidence,'Internships and certifications stored in the profile.'],['Campus opportunity alignment',p.campusOpportunityAlignment,'Relevant companies, eligibility rules, and role alignment.']];return `<details class="readiness-explain"><summary>How this is calculated</summary>${rows.map(([n,v,d])=>`<div class="explain-row"><span>${n}</span><strong>${v}/100</strong><small>${d}</small></div>`).join('')}</details>`}
function recentProgress(){let snaps=state.student.snapshots||[],last=snaps.at(-1),prev=snaps.length>1?snaps.at(-2):null,quiz=state.learning?.lastQuiz,resume=state.resume?.parsed;let items=[];if(prev&&last)items.push(`Readiness ${prev.score} -> ${last.score} (${last.score-prev.score>=0?'+':''}${last.score-prev.score}).`);else items.push('No earlier readiness checkpoint is saved yet.');if(quiz)items.push(`Weekly check: ${Math.round(quiz.score)}% across ${(quiz.skills||[]).join(', ')||'tracked skills'}.`);if(resume)items.push(`Resume evidence updated with ${resume.skills?.length||0} detected technical skills.`);return `<article class="card recent-progress"><div class="label">SINCE LAST CHECK</div><h2>Recent progress</h2><ul>${items.slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></article>`}
function systemStory(){let resume=state.resume?.parsed,quiz=state.learning?.lastQuiz,risk=state.student.academicRiskResult?.risk_level||state.student.academicRiskResult?.result?.risk_level;let steps=[['Profile',state.student.target?role().name:'Target role not selected'],['Evidence',resume?`${resume.skills?.length||0} resume skills`:'Resume not analyzed'],['Analyze',`${readiness()}/100 readiness`],['Recommend',nextAction().name],['Act',`${roadmap().flatMap(p=>p.items).filter(i=>i.done).length} roadmap actions done`],['Measure',quiz?`${Math.round(quiz.score)}% weekly check`:'Weekly check pending']];if(risk)steps.push(['Academic',`${risk} risk`]);return `<article class="card system-story"><div class="label">CONNECTED INTELLIGENCE LOOP</div><div>${steps.map(([n,v])=>`<span><strong>${esc(n)}</strong><small>${esc(v)}</small></span>`).join('')}</div></article>`}
function whyThisText(skill,r=role()){let g=gaps(r).find(x=>x.name===skill),companies=relevantCompanies(r).length,evidence=evidenceForSkill(skill);if(!g)return `${skill} is currently covered for ${r.name}; keep adding visible project or resume proof so the signal stays credible.`;let ev=evidence.some(x=>/^No direct evidence/.test(x))?'there is no direct saved evidence yet':'existing evidence is still below the target level';return `${skill} is required at ${g.need}% for ${r.name}, your current signal is ${g.current}%, ${ev}, and ${companies} relevant campus opportunities use this role path.`}
function todayPriorities(){let a=nextAction(),risk=state.student.academicRiskResult?.risk_level||state.student.academicRiskResult?.result?.risk_level,items=[`${a.name} - ${whyThisText(a.name)}`,'Complete the weekly skill check to keep role compatibility current.'];if(risk)items.push(`Academic risk is ${risk}. Keep academic-risk interventions separate from placement readiness.`);else items.push('Run the academic-risk check if you want early-warning guidance.');return `<article class="card today-priorities"><div class="label">TODAY</div><h2>Today's priorities</h2><ol>${items.slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></article>`}
const dashboardPolishBase=dashboard;
dashboard=function(){let html=dashboardPolishBase();if(!state.student.target)return html;html=html.replace('<div class="sub">Preparedness, not placement probability</div>',`<div class="sub">Preparedness, not placement probability ${info('Placement readiness','A weighted preparedness score from skill alignment, project/resume evidence, academics, experience, and campus opportunity alignment. It is not placement probability.')}</div>${readinessExplain()}`);html=html.replace('<div class="label">Campus alignment</div>',`<div class="label">Campus alignment ${info('Campus alignment','How well the selected role connects with current campus opportunities and eligibility rules.')}</div>`);html=html.replace('<div class="label">Opportunity access</div>',`<div class="label">Opportunity access ${info('Opportunity access','Count of relevant company opportunities where current hard rules and core-skill threshold are satisfied.')}</div>`);return html.replace('<section class="academic-risk card"',todayPriorities()+'<section class="academic-risk card"')}
roleCards=function(list){return list.map(r=>{let isTarget=r.id===state.student.target,score=roleScore(r);return `<article class="card entity"><div class="label">${r.cat}</div><h3>${r.name}</h3><p>${r.desc}</p><div class="bar"><i style="width:${score}%"></i></div><small>${score}% skill alignment ${info('Skill alignment','Coverage of this role requirement list by your saved skill levels and weekly-check adjustment.')} · ${campus(r)}% campus alignment</small><footer><button data-target="${r.id}" class="${isTarget?'lime':''}">${isTarget?'Primary goal':'Set goal'}</button><button data-compare="${r.id}">${compare.includes(r.id)?'Selected':'Compare'}</button></footer></article>`}).join('')}
function roadmapDetail(skill){let low=(state.student.skills[skill]||0)<35;if(/REST APIs|Express|Node|SQL/i.test(skill))return 'Build or extend a backend feature with a real API endpoint, validation, and saved data evidence.';if(/React|HTML|CSS|JavaScript|TypeScript/i.test(skill))return 'Add a small interface feature and connect it to real profile or project data.';if(/DSA/i.test(skill))return 'Practice the core topic behind your weakest weekly-check signal, then retake the check.';if(/Git|GitHub/i.test(skill))return 'Publish or update a real project repository so the evidence is visible.';return low?'Start with one focused practice task, then add evidence to your profile.':'Turn this into visible project or resume evidence.'}
function roadmapEvidenceIntent(skill){if(/DSA/i.test(skill))return 'Weekly assessment evidence';if(/Git|GitHub/i.test(skill))return 'Repository / verified-link evidence';if(/React|HTML|CSS|JavaScript|TypeScript|REST APIs|Express|Node|SQL/i.test(skill))return 'Project evidence';if(/Statistics|Machine Learning|Pandas|TensorFlow|Power BI/i.test(skill))return 'Project or assessment evidence';return 'Activity only'}
function roadmapWhyBlock(item,ev,r=role()){return `<details class="why-this"><summary>Why this?</summary><div class="roadmap-why-grid"><div><span>Current evidence</span><strong>${ev.evidenceScore}</strong></div><div><span>Role requirement</span><strong>${item.need}</strong></div><div><span>Gap</span><strong>${item.gap}</strong></div><div><span>Status</span><strong>${esc(ev.status)}</strong></div><div><span>Confidence</span><strong>${esc(ev.evidenceConfidence)}</strong></div></div><p>${esc(item.skill)} is ${item.gap===gaps(r)[0]?.gap?'your largest current':'a current'} ${esc(r.name)} evidence gap. Improving evidence for this skill would strengthen your ${esc(r.name)} role alignment.</p></details>`}
function roadmapActionCard(item,index,primary=false){let ev=getSkillEvidence(item.skill,role()),pct=item.need?Math.min(100,Math.round(ev.evidenceScore/item.need*100)):0,statusClass=ev.className||'',completed=item.done;return `<article class="roadmap-action-card ${primary?'primary-focus':''} ${completed?'done':''}"><div class="roadmap-action-index">${String(index+1).padStart(2,'0')}</div><div class="roadmap-action-main"><div class="roadmap-action-top"><div><div class="label">${esc(item.skill)}</div><h3>${esc(item.name)}</h3></div><span class="constellation-status ${statusClass}">${esc(ev.status)}</span></div><div class="roadmap-scoreline"><strong>${ev.evidenceScore} evidence / ${item.need} required</strong><span>${item.gap}-point gap - ${esc(ev.evidenceConfidence)} confidence</span></div><div class="bar" aria-label="${esc(item.skill)} evidence score compared with role requirement"><i style="width:${pct}%"></i></div><div class="roadmap-action-detail"><div><span>Recommended activity</span><p>${esc(roadmapDetail(item.skill))}</p></div><div><span>Evidence this action should produce</span><strong>${esc(roadmapEvidenceIntent(item.skill))}</strong></div></div>${completed?'<p class="roadmap-complete-note">Activity completed. Skill evidence will update when new evidence is added or validated.</p>':''}${roadmapWhyBlock(item,ev)}<label class="roadmap-check"><input type="checkbox" data-road="${esc(item.id)}" ${completed?'checked':''}> <span>${completed?'Activity completed':'Mark activity complete'}</span></label></div></article>`}
function roadmapPersonalActions(custom){return `<article class="card roadmap-personal"><div class="section-head"><div><div class="label">PERSONAL ACTIONS</div><h2>Add your own activity</h2></div></div><p class="sub">Personal actions track progress only. They do not change skill evidence unless evidence is added separately.</p><div class="roadmap-personal-form"><input id="custom-task" placeholder="e.g. Deploy my API project"><button id="add-task">Add action</button></div><div id="custom-list" class="roadmap-custom-list">${custom.map(x=>`<div class="row roadmap-row ${x.completed?'done':''}"><input type="checkbox" data-custom-road="${esc(x.id)}" ${x.completed?'checked':''}><div class="row-main"><strong>${esc(x.text)}</strong><small>${x.completed?'Activity completed':'Activity tracking only'} - does not count as project or skill evidence.</small></div></div>`).join('')||'<p class="sub">No personal roadmap actions yet.</p>'}</div></article>`}
function roleExplanation(r){let req=Object.keys(r.req),matched=req.filter(s=>skillVal(s)>=r.req[s]*.75),near=req.filter(s=>skillVal(s)>0&&skillVal(s)<r.req[s]*.75),open=gaps(r).slice(0,3),fast=open[0];return `<details class="role-explain"><summary>Why this role?</summary><h4>Why you match</h4>${matched.length?`<ul>${matched.slice(0,4).map(s=>`<li>${esc(s)} - ${skillVal(s)} evidence / ${r.req[s]} required.</li>`).join('')}</ul>`:near.length?`<p>${esc(near.slice(0,3).join(', '))} shows some evidence, but needs more depth.</p>`:'<p>No strong saved skill evidence is mapped to this role yet.</p>'}<h4>What is holding you back</h4>${open.length?`<ul>${open.map(g=>`<li>${esc(g.name)} - ${g.current} evidence / ${g.need} required.</li>`).join('')}</ul>`:'<p>The main listed role requirements are currently covered.</p>'}<h4>Biggest priority</h4><p>${fast?esc(roadmapDetail(fast.name)):'Keep adding project, resume, and weekly-check evidence.'}</p></details>`}
roleCards=function(list){return list.map(r=>{let isTarget=r.id===state.student.target,score=roleScore(r);return `<article class="card entity role-card"><div class="label">${r.cat}</div><h3>${r.name}</h3><p>${r.desc}</p><div class="bar"><i style="width:${score}%"></i></div><small>${score}% skill alignment ${info('Skill alignment','Coverage of this role requirement list by centralized profile, project, assessment, resume, and roadmap evidence.')} - ${campus(r)}% campus alignment</small>${roleExplanation(r)}<footer><button data-target="${r.id}" class="${isTarget?'lime':''}">${isTarget?'Primary goal':'Set goal'}</button><button data-compare="${r.id}">${compare.includes(r.id)?'Selected':'Compare'}</button></footer></article>`}).join('')}
function customRoadmapItems(){let current=state.student.target||null;return (state.student.customRoadmapActions||[]).filter(x=>!x.roleId||x.roleId===current)}
roadmapPage=function(){if(!state.student.target)return layout(`<div class="page-head"><h1>Your roadmap.</h1><p>Choose a target role to generate your role-relative action plan.</p></div><article class="card roadmap-empty"><h2>Choose a target role</h2><p>Your roadmap will be generated from ASCENTRA Core skill evidence gaps.</p><button class="primary" data-nav="roles">Explore roles</button></article>`);let r=role(),phases=roadmap(),all=phases.flatMap(p=>p.items),done=all.filter(i=>i.done).length,total=all.length,top=all[0],custom=customRoadmapItems();if(!total)return layout(`<div class="page-head"><h1>Your ${esc(r.name)} roadmap.</h1><p>Your current evidence covers the core requirements for this role.</p></div><article class="card roadmap-empty"><h2>Requirements covered</h2><p>Keep strengthening validated evidence through projects, resume updates, and Weekly Skill Checks.</p></article>${roadmapPersonalActions(custom)}`);return layout(`<section class="roadmap-page"><div class="page-head roadmap-head"><div><h1>Your ${esc(r.name)} roadmap.</h1><p>A role-relative action plan generated from your current ASCENTRA evidence gaps.</p></div><button data-view="simulator">Open What-if Lab</button></div><article class="card roadmap-overview"><div><div class="label">TARGET ROLE</div><h2>${esc(r.name)}</h2><p>${done} of ${total} recommended activities completed</p></div><div class="roadmap-overview-focus"><span>Primary focus</span><strong>${esc(top.skill)}</strong><small>${top.current} evidence / ${top.need} required - ${top.gap}-point evidence gap</small></div><div class="roadmap-progress"><div class="bar"><i style="width:${total?done/total*100:0}%"></i></div><small>Completing an action records activity. Your skill evidence changes only when new evidence is added or validated.</small></div></article><section class="roadmap-next-best"><div class="section-head"><div><div class="label">NEXT BEST ACTION</div><h2>${esc(top.skill)}</h2></div><div class="chips"><button data-view="simulator">Simulate improvement</button><button data-skill-evidence="${esc(top.skill)}">View skill evidence</button></div></div>${roadmapActionCard(top,0,true)}</section><section class="roadmap-priority-list">${phases.map(p=>`<section class="roadmap-priority-section"><div class="section-head"><div><div class="label">PRIORITY BAND</div><h2>${esc(p.name)}</h2></div></div><div class="roadmap-actions">${p.items.map((i,idx)=>roadmapActionCard(i,all.findIndex(x=>x.id===i.id),i.id===top.id)).join('')}</div></section>`).join('')}</section>${roadmapPersonalActions(custom)}<article class="card roadmap-method-note"><strong>How this roadmap updates</strong><p>Priorities regenerate when your target role or accepted evidence changes, such as profile evidence, projects, resume evidence, or Weekly Skill Checks. Completed activity history is preserved by role-skill action ID.</p></article></section>`)}
function simResultEmpty(gs,base,fit){return `<div class="label">CURRENT</div><div class="sim-impact"><div><span>Role compatibility</span><strong>${fit}%</strong></div><div><span>Readiness</span><strong>${base}/100</strong></div><div><span>Top skill gap</span><strong>${esc(gs[0]?.name||'None')}</strong></div></div><div class="sim-empty-state"><span>SCENARIO</span><strong>No hypothetical changes yet.</strong><p>Adjust one or more evidence values and run the simulation to compare your current profile with the hypothetical scenario.</p></div>`}
simulatorPage=function(){let gs=gaps().slice(0,6),base=readiness(),fit=roleScore(role());return layout(`<div class="page-head"><h1>What-if lab.</h1><p>Explore hypothetical profile/self evidence changes against the same ASCENTRA Core engine.</p></div><div class="grid two sim-lab"><article class="card"><h2>Simulate skill evidence</h2><p class="sub">Adjust hypothetical profile/self evidence and see how ASCENTRA's canonical career calculations would change.</p>${gs.map(g=>{let id=g.name.replace(/[^a-z]/gi,'');return `<div class="sim-card" data-sim-card="${esc(g.name)}"><div class="gap-top"><strong>${esc(g.name)}</strong><span class="sim-delta" id="sim-delta-${id}">No change</span></div><div class="sim-evidence-grid"><div><span>Current</span><strong>${g.current}</strong></div><div><span>Hypothetical</span><strong id="sim-val-${id}">${g.current}</strong></div><div><span>Role requirement</span><strong>${g.need}</strong></div></div><label class="sim-label" for="sim-${id}">${esc(g.name)} hypothetical profile evidence. Current evidence ${g.current}; role requirement ${g.need}.</label><div class="sim-range-wrap" style="--req:${g.need}%"><input id="sim-${id}" class="sim" data-sim="${esc(g.name)}" data-current="${g.current}" data-need="${g.need}" type="range" min="${g.current}" max="100" value="${g.current}"><i aria-hidden="true"></i></div></div>`}).join('')||'<p class="sub">No open skill gaps for this role.</p>'}<div class="chips"><button class="primary" id="run-sim" disabled>Run simulation</button><button id="reset-sim" disabled>Reset simulation</button></div><p id="sim-helper" class="sub">Adjust at least one value to run a scenario.</p><p class="sub">Simulation only. Hypothetical values are not saved as accepted evidence. Strengthen your real profile through projects, resume updates, profile evidence, or Weekly Skill Checks.</p></article><article class="card readiness sim-results" id="sim-result">${simResultEmpty(gs,base,fit)}</article></div>`)}
function simMetric(label,before,after,suffix=''){let delta=Number(after)-Number(before),text=Number.isFinite(delta)?`${delta>=0?'+':''}${delta}`:'No change';return `<div><span>${esc(label)}</span><strong>${esc(before)}${suffix} -> ${esc(after)}${suffix}</strong><small>${esc(text)}</small></div>`}
function runSim(){let sliders=[...document.querySelectorAll('.sim')],copy=structuredClone(state.student),changes=[];copy.skills={...(copy.skills||{})};sliders.forEach(x=>{let before=+x.dataset.current,after=+x.value;copy.skills[x.dataset.sim]=after;if(after!==before)changes.push({skill:x.dataset.sim,from:before,to:after,delta:after-before,need:+x.dataset.need})});if(!changes.length){updateSimControls();return}let r=role(),baseReady=readiness(r),baseParts=readinessParts(r),baseFit=roleScore(r),baseGap=gaps(r)[0],baseCompanies=relevantCompanies(r).map(c=>Core.eligibility(c,r,coreCtx(state.student)));let simCtx=coreCtx(copy),simReady=Core.readiness(r,simCtx,companies),simParts=Core.readinessParts(r,simCtx,companies),simFit=Core.roleScore(r,simCtx),simGap=Core.gaps(r,simCtx,companies)[0],simCompanies=relevantCompanies(r).map(c=>Core.eligibility(c,r,simCtx));let sameEligibility=baseCompanies.every((e,i)=>e[0]===simCompanies[i]?.[0]),eligibleCount=simCompanies.filter(e=>e[0]==='ELIGIBLE').length,biggest=changes.sort((a,b)=>b.delta-a.delta)[0],companyFit={from:baseCompanies[0]?.[2]?.profileFit??baseFit,to:simCompanies[0]?.[2]?.profileFit??simFit};lastSimulation={date:Date.now(),targetRole:r.name,currentReadiness:baseReady,simulatedReadiness:simReady,delta:simReady-baseReady,changes,skillAlignment:{from:baseParts.skillAlignment,to:simParts.skillAlignment},roleCompatibility:{from:baseFit,to:simFit},companyEligibilityUnchanged:sameEligibility,eligibleCompanies:eligibleCount,companyProfileFit:companyFit,topGap:{from:baseGap?.name||null,to:simGap?.name||null},remainingGaps:Core.gaps(r,simCtx,companies).length,nextBestAction:simGap?.name||null};document.querySelector('#sim-result').innerHTML=`<div class="label">CURRENT / SIMULATED</div><div class="sim-impact refined">${simMetric('Role compatibility',baseFit,simFit,'%')}${simMetric('Readiness',baseReady,simReady)}${simMetric('Profile fit',companyFit.from,companyFit.to,'%')}</div><div class="sim-category-grid"><div><span>Top skill gap</span><strong>${esc(baseGap?.name||'None')} -> ${esc(simGap?.name||'None')}</strong></div><div><span>Eligibility</span><strong>${sameEligibility?'Eligible -> Eligible':'Changed'}</strong><small>${sameEligibility?'No change':'Check company rules'} · ${eligibleCount} relevant eligible</small></div></div><div class="sim-changes"><div class="label">SCENARIO CHANGES</div>${changes.map(x=>`<div><strong>${esc(x.skill)}</strong><span>${x.from} -> ${x.to}</span><small>${x.delta>=0?'+':''}${x.delta} hypothetical profile evidence · required ${x.need}</small></div>`).join('')}</div><div class="sim-next"><span>NEXT PRIORITY AFTER THIS SCENARIO</span><strong>${esc(simGap?.name||'None')}</strong><small>${simGap?`${simGap.gap}-point evidence gap`:'No open gap in this scenario.'}</small></div><p class="sub">Eligibility is based on stored application rules. Profile fit reflects role/evidence alignment.</p><p class="sub">Simulation only. The saved profile is unchanged and no accepted evidence was created.</p>`}
function updateSimControls(){let sliders=[...document.querySelectorAll('.sim')],changed=sliders.some(x=>+x.value!==+x.dataset.current),run=document.querySelector('#run-sim'),reset=document.querySelector('#reset-sim'),helper=document.querySelector('#sim-helper');sliders.forEach(x=>{let delta=+x.value-+x.dataset.current,id=x.dataset.sim.replace(/[^a-z]/gi,''),out=document.querySelector('#sim-val-'+id),d=document.querySelector('#sim-delta-'+id),card=x.closest('.sim-card');if(out)out.textContent=x.value;if(d)d.textContent=delta?`${delta>=0?'+':''}${delta} hypothetical`:'No change';card?.classList.toggle('changed',!!delta)});if(run)run.disabled=!changed;if(reset)reset.disabled=!changed&&!lastSimulation;if(helper)helper.textContent=changed?'Run simulation to compare current and simulated outcomes.':'Adjust at least one value to run a scenario.'}
document.addEventListener('click',e=>{if(!e.target.closest('#reset-sim'))return;e.preventDefault();document.querySelectorAll('.sim').forEach(x=>x.value=x.dataset.current);lastSimulation=null;let gs=gaps().slice(0,6);let panel=document.querySelector('#sim-result');if(panel)panel.innerHTML=simResultEmpty(gs,readiness(),roleScore(role()));updateSimControls()});
const SKILL_EVIDENCE_WEIGHTS=Core.EVIDENCE_WEIGHTS;
const SKILL_EVIDENCE_CAPS=Core.EVIDENCE_CAPS;
const clampScore=Core.clampScore,normalizedSkillText=Core.normalizedSkillText,skillAliases=Core.skillAliases,skillInText=Core.skillInText;
