roadmap=function(r=role()){return Core.roadmap(roleById(r),coreCtx(),companies)}
roleExplanation=function(r){let req=Object.keys(r.req),evidence=req.map(s=>getSkillEvidence(s,r)),matched=evidence.filter(x=>x.evidenceScore>=x.roleRequirement*.75),near=evidence.filter(x=>x.evidenceScore>0&&x.evidenceScore<x.roleRequirement*.75),open=gaps(r).slice(0,3),fast=open[0];return `<details class="role-explain"><summary>Why this role?</summary><h4>Why you match</h4>${matched.length?`<ul>${matched.slice(0,4).map(x=>`<li>${esc(x.skill)} - ${x.evidenceScore} evidence / ${x.roleRequirement} required (${x.evidenceConfidence} confidence).</li>`).join('')}</ul>`:near.length?`<p>${esc(near.slice(0,3).map(x=>x.skill).join(', '))} shows some evidence, but needs more depth.</p>`:'<p>No strong saved skill evidence is mapped to this role yet.</p>'}<h4>What is holding you back</h4>${open.length?`<ul>${open.map(g=>`<li>${esc(g.name)} - ${g.current} evidence / ${g.need} required.</li>`).join('')}</ul>`:'<p>The main listed role requirements are currently covered.</p>'}<h4>Biggest priority</h4><p>${fast?esc(roadmapDetail(fast.name)):'Keep adding project, resume, and weekly-check evidence.'}</p></details>`}
eligibility=function(c){return Core.eligibility(c,role(),coreCtx())}
function resumeEvidenceItems(){let d=state.resume?.parsed;if(!d)return [];let text=String(d.text||'').toLowerCase();return (d.skills||[]).slice(0,12).map(skill=>{let token=skill.toLowerCase().replace('.js',''),project=(d.projects||[]).some(p=>p.toLowerCase().includes(token))||/project/i.test(text)&&text.includes(token),experience=d.sections?.experience&&text.includes(token),tool=/Git|GitHub|VS Code|Docker|AWS|Power BI|Figma/i.test(skill),type=project?'Project evidence':experience?'Experience evidence':tool?'Tool evidence':'Skill mentioned';return {skill,type,detail:project?'Found near project evidence in the uploaded resume.':experience?'Found with experience-section evidence.':tool?'Detected as a tool or platform signal.':'Detected in resume text or skills section only.'}})}
const resumeBeforeEvidenceQuality=resumePage;
resumePage=function(){let html=resumeBeforeEvidenceQuality(),items=resumeEvidenceItems();if(!items.length)return html;let grid=`<article class="card resume-evidence-quality"><div class="section-head"><div><div class="label">EVIDENCE QUALITY</div><h2>What each resume skill proves</h2></div><span class="tag">PARSED RESUME</span></div><div class="resume-evidence-grid">${items.map(x=>`<div><strong>${esc(x.skill)}</strong><span>${esc(x.type)}</span><small>${esc(x.detail)}</small></div>`).join('')}</div><p class="sub">ASCENTRA treats project and experience evidence as stronger than a single keyword mention.</p></article>`;return html.replace('</main>',grid+'</main>')}
function skillEvidenceDetailRows(ev){let s=ev.sources,rows=[];if(s.profile.available)rows.push(['Profile',`${s.profile.score}% self-reported profile score`]);if(s.resume.available)rows.push(['Resume',s.resume.quality==='contextual'?'Mentioned in resume context':'Skill mentioned in resume']);if(s.project.available)rows.push(['Project',`${s.project.quality==='applied'?'Applied use':'Mentioned'}${s.project.projects?.length?`: ${s.project.projects.slice(0,2).join(', ')}`:''}`]);rows.push(['Weekly check',s.assessment.available?`${s.assessment.score}% ${s.assessment.quality==='per_skill'?'per-skill validation':'shared-check signal'}`:'Not validated']);if(s.roadmap.quality==='completed')rows.push(['Roadmap','Activity completed; not counted as skill evidence']);else if(gaps(role()).some(g=>g.name===ev.skill))rows.push(['Roadmap','Recommended/in progress opportunity']);return rows.map(([a,b])=>`<div class="explain-row"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}
document.addEventListener('click',e=>{let b=e.target.closest('[data-skill-evidence]');if(!b)return;let skill=b.dataset.skillEvidence,ev=getSkillEvidence(skill,role()),gap=ev.gap?`${ev.gap}-point gap`:'Requirement covered';modal(`<div class="label">SKILL EVIDENCE</div><div class="section-head"><div><h2>${esc(skill)}</h2><p>${esc(ev.roleName)} readiness estimate</p></div><span class="constellation-status ${ev.className}">${esc(ev.status)}</span></div><div class="constellation-metrics"><div><span>Evidence strength</span><strong>${ev.evidenceScore}%</strong></div><div><span>Requirement</span><strong>${ev.roleRequirement||0}%</strong></div><div><span>Gap</span><strong>${esc(gap)}</strong></div><div><span>Confidence</span><strong>${esc(ev.evidenceConfidence)}</strong></div></div><h3>Evidence sources</h3>${skillEvidenceDetailRows(ev)}<p class="sub">Profile scores are self-reported unless another ASCENTRA source validates them.</p><button class="close-modal">Close</button>`)});
function enhanceSkillEvidence(){if(view!=='profile')return;document.querySelectorAll('.card .row-main strong').forEach(el=>{let skill=el.textContent.trim(),row=el.closest('.row');if(!row||row.querySelector('[data-skill-evidence]')||!Object.hasOwn(state.student.skills||{},skill))return;let btn=document.createElement('button');btn.type='button';btn.className='mini-action';btn.dataset.skillEvidence=skill;btn.textContent='Evidence';row.insertBefore(btn,row.querySelector('[data-remove-skill]')||null)})}
new MutationObserver(()=>enhanceSkillEvidence()).observe(document.querySelector('#app'),{childList:true,subtree:true});
function opportunityThreshold(need){return need}
function fmtReq(n){return Number.isInteger(n)?String(n):String(Math.round(n*100)/100)}
function companyOpportunityBlockers(c,r=role()){return Core.gaps(r,coreCtx(),companies).slice(0,3).map(g=>({skill:g.name,evidence:g.current,roleRequirement:g.need,threshold:g.need,gap:g.gap,status:g.status,confidence:g.confidence}))}
