function requirementRow(name,student,required,state,detail=''){return `<div class="requirement-row ${state}"><span>${esc(name)}</span><strong>${esc(student)}</strong><small>${esc(required)} - ${checkLabel(state)}${detail?` - ${esc(detail)}`:''}</small></div>`}
function eligibilityRows(c,r=role()){let s=state.student,e=Core.eligibility(c,r,coreCtx()),detail=e[2]||{},dept=Core.departmentPass(s.department,c.depts),back=(s.backlogs||0)<=c.backlogs,cgpa=Number(s.cgpa)>=c.cgpa,cgpaNear=!cgpa&&Number(s.cgpa)>=c.cgpa-.35,roleRelevant=c.roleIds.includes(r.id);return `<div class="eligibility-grid company-detail-grid">${requirementRow('CGPA',`Student: ${s.cgpa??'not provided'}`,`Required: >= ${c.cgpa}`,cgpa?'pass':cgpaNear?'near':'fail')}${requirementRow('Backlogs',`Student: ${s.backlogs??0}`,`Allowed: <= ${c.backlogs}`,back?'pass':'fail')}${requirementRow('Department',`Student: ${s.department||'Not provided'}`,`Accepted: ${c.depts.join(', ')}`,dept?'pass':'fail',`normalized ${detail.departmentFamily||Core.normalizeDepartment(s.department)}`)}${requirementRow('Target role',r.name,roleRelevant?'Available at this company':'Not listed for this company',roleRelevant?'pass':'fail')}</div>`}
function companyPrimaryBlocker(c,r=role()){let e=Core.eligibility(c,r,coreCtx()),failed=e[2]?.failed||[];if(failed.includes('department'))return {skill:'Department',text:`${state.student.department||'Not provided'} not in ${c.depts.join(', ')}`};if(failed.includes('backlogs'))return {skill:'Backlogs',text:`${state.student.backlogs??0} / ${c.backlogs} allowed`};if(failed.includes('cgpa'))return {skill:'CGPA',text:`${state.student.cgpa??'not provided'} / ${c.cgpa} required`};if(failed.includes('target role'))return {skill:'Target role',text:`${r.name} is not listed`};return null}
companyModal=function(c,r=role()){let e=Core.eligibility(c,r,coreCtx()),detail=e[2]||{},rolesText=c.roleIds.map(id=>roles.find(r=>r.id===id)?.name||id).join(', '),eligibilityIssue=companyPrimaryBlocker(c,r),prep=companyPreparationPriority(c,r);modal(`<div class="company-detail"><div class="label">COMPANY</div><div class="section-head"><div><h2>${esc(c.name)}</h2><p>${esc(c.industry)}</p></div>${pill(e[0])}</div><section><div class="label">OPPORTUNITY</div><p><strong>Relevant roles:</strong> ${esc(rolesText)}</p><p class="sub">Assessing against: ${esc(r.name)}</p><p class="sub">Cycles: ${c.years.join(', ')} - typical package ${c.pkg} LPA</p></section><section><div class="label">ELIGIBILITY</div><p>${esc(e[1])}</p><h3>Requirement check</h3>${eligibilityRows(c,r)}</section><section class="company-fit-note"><div><span>Profile fit</span><strong>${detail.profileFit??roleScore(r)}%</strong><small>Based on ${esc(r.name)} alignment</small></div><p>Profile fit measures your current evidence alignment with the role. It does not determine company eligibility or predict hiring.</p></section><section class="company-next-action"><div class="label">ROLE PREPARATION</div>${eligibilityIssue?`<h3>${esc(eligibilityIssue.skill)}</h3><p>${esc(eligibilityIssue.text)}</p>`:prep?`<h3>${esc(prep.skill)}</h3><p>${prep.evidence} evidence / ${fmtReq(prep.roleRequirement)} role requirement.</p><p>${prep.gap}-point evidence gap. This is a ${esc(r.name)} preparation gap, not a company-specific application requirement.</p>`:'<p class="sub">Configured role requirements are currently covered.</p>'}<div class="chips"><button data-company-view="roadmap">Build roadmap</button><button data-company-view="simulator">Simulate improvement</button></div></section><p class="sub">Company eligibility is rule-based from stored campus opportunity criteria and your live profile. It is not an ML placement prediction.</p><button class="close-modal">Close</button></div>`)}
companyCards=function(list,r=role()){return list.map(c=>{let e=Core.eligibility(c,r,coreCtx()),detail=e[2]||{},rs=c.roleIds.map(id=>roles.find(r=>r.id===id)?.name||id).join(', '),fit=detail.profileFit??roleScore(r),eligibilityIssue=companyPrimaryBlocker(c,r),prep=companyPreparationPriority(c,r);return `<article class="card entity company-card"><div class="section-head"><span class="label">${esc(c.industry)}</span>${pill(e[0])}</div><h3>${esc(c.name)}</h3><p>${esc(rs)}</p><div class="company-fit"><div><span>Eligibility</span><strong>${esc(e[0])}</strong><small>${esc(e[1])}</small></div><div><span>Profile fit</span><strong>${fit}%</strong><small>Based on ${esc(r.name)} alignment</small></div></div><div class="company-prep-line"><span>${eligibilityIssue?'Eligibility issue':'Preparation priority'}</span><strong>${esc(eligibilityIssue?.skill||prep?.skill||'Role requirements covered')}</strong><small>${eligibilityIssue?esc(eligibilityIssue.text):prep?`${prep.evidence} evidence / ${fmtReq(prep.roleRequirement)} required`:''}</small></div><div class="company-rule-line">CGPA >= ${c.cgpa} - Backlogs <= ${c.backlogs}</div><footer><small>${detail.departmentFamily?`Department family: ${esc(detail.departmentFamily)}`:`Accepted: ${esc(c.depts.join(', '))}`}</small><button data-company="${c.id}" data-company-role="${r.id}">View details</button></footer></article>`}).join('')||'<article class="card"><p>No matching campus opportunities were found with these filters.</p></article>'}
