const edgeStyle=(x1,y1,x2,y2,w=1)=>{let dx=x2-x1,dy=y2-y1,len=Math.hypot(dx,dy),angle=Math.atan2(dy,dx)*180/Math.PI;return `left:${x1}%;top:${y1}%;width:${len}%;transform:rotate(${angle}deg);opacity:${Math.min(.75,.25+w*.006)};height:${Math.max(1,Math.min(5,w/18))}px`};
const constellationBase=constellationPage;
constellationPage=function(){let r=role(),skills=Object.keys(r.req).slice(0,6),nodes=[{cl:'student',x:50,y:45,n:state.student.name||'Student'},{cl:'role',x:50,y:14,n:r.name},...skills.map((s,i)=>({cl:'',x:13+i*15,y:76,n:s}))],edges=[edgeStyle(50,45,50,20,roleScore(r)),...skills.map((s,i)=>edgeStyle(50,22,13+i*15,72,r.req[s]))];return layout(`<div class="page-head"><h1>Your career constellation.</h1><p>Skills, role requirements and campus opportunities shown as explainable relationships.</p></div><div class="constellation upgraded">${edges.map(s=>`<i class="edge" style="${s}"></i>`).join('')}${nodes.map(x=>`<button class="node ${x.cl}" style="left:calc(${x.x}% - 37px);top:calc(${x.y}% - 37px)" data-node="${esc(x.n)}">${esc(x.n)}</button>`).join('')}</div><article class="card constellation-panel"><div class="label">RELATIONSHIP VIEW</div><p>Click a skill node to see its required level, current evidence score, and connected campus opportunities for ${esc(r.name)}.</p></article>`)}
nodeModal=function(n){let r=role(),ev=getSkillEvidence(n,r),g=gaps(r).find(x=>x.name===n),cs=relevantCompanies(r).filter(c=>c.roleIds.includes(r.id)),importance=r.req[n];modal(`<h2>${esc(n)}</h2>${importance?`<p><strong>Evidence score:</strong> ${ev.evidenceScore}% - <strong>Role requirement:</strong> ${importance}% - <strong>Confidence:</strong> ${esc(ev.evidenceConfidence)}</p><p>${g?`Gap: ${g.gap}% - weighted priority ${g.impact}.`:'This requirement is currently covered for the selected role.'}</p><h3>Evidence</h3><ul class="evidence-list">${evidenceForSkill(n,r).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><strong>Related opportunities:</strong> ${cs.map(c=>c.name).join(', ')||'No target-role opportunities'}</p>`:`<p>This node represents your selected role or profile anchor.</p><p><strong>Skill alignment:</strong> ${roleScore(r)}%</p>`}<button class="close-modal">Close</button>`)}
let constellationSelectedSkill=null;
function constellationSkillStatus(skill,r=role()){return getSkillEvidence(skill,r)}
function constellationSkillPositions(skills){let many=skills.length>6,cols=many?Math.ceil(skills.length/2):Math.max(skills.length,1);return skills.map((skill,i)=>{let row=many&&i>=cols?1:0,slot=many?i%cols:i,count=row&&many?skills.length-cols:cols,x=160+(count<=1?340:(680/(count-1))*slot),y=row?500:many?380:420;return {skill,x,y}})}
function constellationPath(a,b,curve=55){return `M ${a.x} ${a.y} C ${a.x} ${a.y+curve}, ${b.x} ${b.y-curve}, ${b.x} ${b.y}`}
function constellationWhy(skill,r=role()){if(/React|HTML|CSS|JavaScript|TypeScript/i.test(skill))return `${skill} connects your profile to ${r.name} because this role depends on building clear, usable product interfaces.`;if(/Node|Express|REST|SQL|Docker|AWS|Linux|CI\/CD|Kubernetes/i.test(skill))return `${skill} matters for ${r.name} because it supports reliable systems, services, and delivery work employers expect in this path.`;if(/Python|Statistics|Machine Learning|Pandas|TensorFlow|Power BI/i.test(skill))return `${skill} matters for ${r.name} because it helps turn data and models into useful, demonstrable work.`;if(/DSA|Git|GitHub/i.test(skill))return `${skill} strengthens your ${r.name} profile because it supports problem solving, collaboration, and visible engineering evidence.`;return `${skill} is part of the current requirement set for ${r.name}.`}
function constellationNextStep(skill,status,r=role()){if(status.gap>0)return roadmapDetail(skill);return evidenceForSkill(skill).some(x=>/No direct evidence/.test(x))?'Add visible evidence through your profile, resume, weekly check, or a small project.':`Keep this evidence current and use it in projects or resume bullets for ${r.name}.`}
function constellationInspector(skill,r=role()){let skills=Object.keys(r.req);if(!skill||!skills.includes(skill))return `<article class="card constellation-panel"><div class="label">RELATIONSHIP VIEW</div><h2>Select a skill</h2><p>Select a skill to understand its current evidence, required level, career relevance, and connected opportunities.</p><div class="constellation-empty">Complete a weekly check, update your resume, or add profile skills to strengthen this map.</div></article>`;let status=constellationSkillStatus(skill,r),gap=status.gap===0?`${Math.max(0,status.evidenceScore-status.roleRequirement)} above target`:`${status.gap}-point gap`,evidence=evidenceForSkill(skill,r),cs=relevantCompanies(r).slice(0,4),hasGap=status.gap>0;return `<article class="card constellation-panel selected"><div class="label">RELATIONSHIP VIEW</div><div class="section-head"><div><h2>${esc(skill)}</h2><p>${esc(constellationWhy(skill,r))}</p></div><span class="constellation-status ${status.className}">${esc(status.label)}</span></div><div class="constellation-metrics"><div><span>Evidence score</span><strong>${status.evidenceScore}%</strong></div><div><span>Target level</span><strong>${status.roleRequirement}%</strong></div><div><span>Gap</span><strong>${esc(gap)}</strong></div><div><span>Confidence</span><strong>${esc(status.evidenceConfidence)}</strong></div></div><h3>Evidence sources</h3><ul class="evidence-list">${evidence.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Connected opportunities</h3>${cs.length?`<div class="constellation-opportunity-list">${cs.map(c=>`<span>${esc(c.name)}</span>`).join('')}</div>`:'<p class="sub">No mapped campus opportunities are connected to this target role yet.</p>'}<h3>Recommended next step</h3><p>${esc(constellationNextStep(skill,status,r))}</p>${hasGap?`<button class="primary" data-constellation-road="${esc(skill)}">Add to roadmap</button>`:`<button data-nav="profile">Update evidence</button>`}</article>`}
function constellationNode(n){return `<button class="constellation-node ${n.type||''} ${n.status?.className||''} ${n.selected?'selected':''}" style="left:${n.x/10}%;top:${n.y/6.2}%;" ${n.type==='skill'?`data-constellation-skill="${esc(n.id)}" aria-pressed="${n.selected?'true':'false'}"`:''}><span>${esc(n.label)}</span>${n.sub?`<small>${esc(n.sub)}</small>`:''}</button>`}
constellationPage=function(){let r=role(),skills=Object.keys(r.req),selected=skills.includes(constellationSelectedSkill)?constellationSelectedSkill:null;if(constellationSelectedSkill&&!selected)constellationSelectedSkill=null;let skillPoints=constellationSkillPositions(skills),rolePt={x:500,y:85},studentPt={x:500,y:245},opps=relevantCompanies(r).slice(0,4),oppPoints=opps.map((c,i)=>({id:c.id,label:c.name,x:170+(opps.length<=1?330:(660/(opps.length-1))*i),y:565,type:'opportunity',sub:c.industry})),skillNodes=skillPoints.map(p=>{let st=constellationSkillStatus(p.skill,r);return {...p,id:p.skill,label:p.skill,type:'skill',status:st,sub:st.label,selected:p.skill===selected}}),nodes=[{id:'role',label:r.name,x:rolePt.x,y:rolePt.y,type:'role',sub:'Target role'},{id:'student',label:state.student.name||'You',x:studentPt.x,y:studentPt.y,type:'student',sub:`${roleScore(r)}% alignment`},...skillNodes,...oppPoints],skillEdges=skillPoints.map(p=>({skill:p.skill,d:constellationPath(studentPt,p,70),status:constellationSkillStatus(p.skill,r)})),source=skillPoints.find(p=>p.skill===selected)||studentPt,oppEdges=selected?oppPoints.map(o=>constellationPath(source,o,45)):[];return layout(`<div class="page-head constellation-title"><h1>Your career constellation.</h1><p>See how your current evidence connects to ${esc(r.name)} and the campus opportunities around it.</p></div><section class="constellation-workspace ${selected?'has-selection':''}"><div class="constellation upgraded" data-selected="${esc(selected||'')}"><svg class="constellation-svg" viewBox="0 0 1000 620" preserveAspectRatio="none" aria-hidden="true"><path class="constellation-edge main" d="${constellationPath(rolePt,studentPt,50)}"></path>${skillEdges.map(e=>`<path class="constellation-edge skill ${e.status.className} ${selected&&e.skill!==selected?'muted':''} ${selected===e.skill?'active':''}" d="${e.d}"></path>`).join('')}${oppEdges.map(d=>`<path class="constellation-edge opportunity active" d="${d}"></path>`).join('')}</svg>${nodes.map(n=>constellationNode(n)).join('')}</div><div class="constellation-legend"><span><i class="student"></i>You</span><span><i class="role"></i>Target role</span><span><i class="skill"></i>Skill</span><span><i class="opportunity"></i>Opportunity</span><span><b class="ready"></b>Ready</span><span><b class="developing"></b>Developing</span><span><b class="priority"></b>Priority gap</span></div>${constellationInspector(selected,r)}</section>`)}
