 Python:['Which Python structure stores key-value pairs?',['list','dict','tuple','set'],1],
 Statistics:['Which metric summarizes the spread of values?',['Mean','Standard deviation','Mode','Label'],1],
 'Machine Learning':['What is model evaluation used for?',['Checking performance on unseen data','Changing CSS','Opening a port','Creating routes'],0],
 Pandas:['Which Pandas object usually represents a table?',['Series','DataFrame','Socket','Promise'],1],
 TensorFlow:['What does a training epoch mean?',['One pass through the training data','A database migration','A CSS animation frame','A deployment region'],0],
 SQL:['Which SQL clause filters rows?',['GROUP BY','WHERE','ORDER BY','JOIN'],1],
 'Node.js':['What is Node.js commonly used for?',['Running JavaScript on the server','Styling buttons','Training only CNN models','Creating images'],0],
 'Express.js':['What does Express mainly help build?',['HTTP APIs and routes','Spreadsheet formulas','CSS variables','Git commits'],0],
 JavaScript:['Which value is a JavaScript promise used to represent?',['A future async result','A database schema only','A CSS selector','A compiled binary'],0],
