function aiPlainText(text){return esc(text).replace(/\n/g,'<br>')}
function aiInlineMarkdown(text){
  let codes=[];
  let safe=esc(text).replace(/`([^`\n]+)`/g,(_,code)=>{let id=`\u0000CODE${codes.length}\u0000`;codes.push(`<code>${code}</code>`);return id});
  safe=safe
    .replace(/\*\*([^*\n][\s\S]*?[^*\n])\*\*/g,'<strong>$1</strong>')
    .replace(/__([^_\n][\s\S]*?[^_\n])__/g,'<strong>$1</strong>')
    .replace(/(^|[\s(])\*([^*\n]+)\*/g,'$1<em>$2</em>')
    .replace(/(^|[\s(])_([^_\n]+)_/g,'$1<em>$2</em>');
  return safe.replace(/\u0000CODE(\d+)\u0000/g,(_,i)=>codes[Number(i)]||'');
}
function aiFlushParagraph(lines,out){if(lines.length){out.push(`<p>${aiInlineMarkdown(lines.join('\n')).replace(/\n/g,'<br>')}</p>`);lines.length=0}}
function aiFlushList(list,out){if(list.items.length){let tag=list.type==='ol'?'ol':'ul';out.push(`<${tag}>${list.items.map(x=>`<li>${aiInlineMarkdown(x)}</li>`).join('')}</${tag}>`);list.items=[];list.type=''}}
function aiMarkdown(text){
  let lines=String(text||'').replace(/\r\n?/g,'\n').split('\n'),out=[],paragraph=[],list={type:'',items:[]},inCode=false,code=[];
  for(let raw of lines){
    let fence=raw.match(/^\s*```/);
    if(fence){
      if(inCode){out.push(`<pre><code>${esc(code.join('\n'))}</code></pre>`);code=[];inCode=false}
      else{aiFlushParagraph(paragraph,out);aiFlushList(list,out);inCode=true}
      continue;
    }
    if(inCode){code.push(raw);continue}
    let ordered=raw.match(/^\s*\d+[.)]\s+(.+)$/),bullet=raw.match(/^\s*[-*]\s+(.+)$/);
    if(ordered||bullet){
      aiFlushParagraph(paragraph,out);
      let type=ordered?'ol':'ul';
      if(list.type&&list.type!==type)aiFlushList(list,out);
      list.type=type;
      list.items.push((ordered||bullet)[1]);
      continue;
    }
    if(!raw.trim()){aiFlushParagraph(paragraph,out);aiFlushList(list,out);continue}
    aiFlushList(list,out);
    paragraph.push(raw);
  }
  if(inCode)out.push(`<pre><code>${esc(code.join('\n'))}</code></pre>`);
  aiFlushParagraph(paragraph,out);
  aiFlushList(list,out);
  return out.join('');
}
