function guidePage(){return layout(ascentraAIWidget('full-ai'))}
function dashboardAcademicSummary(){let input=academicRiskDefaults(),result=state.student.academicRiskResult?.result||state.student.academicRiskResult;if(!result)return `<div class="dash-mini-grid"><div><span>Risk indicator</span><strong>Not checked</strong></div><div><span>Current level</span><strong>Unavailable</strong></div></div><p class="sub">Check your academic health to add a prototype early-warning estimate.</p><p class="dash-note">For academic planning, not a final outcome.</p><button data-view="academic">View Academic Health</button>`;return `<div class="dash-mini-grid"><div><span>Risk indicator</span><strong>${esc(riskPercent(result))}</strong></div><div><span>Current level</span><strong>${esc(result.risk_level)}</strong></div><div><span>Trend</span><strong>${esc(input.academic_trend||'Not set')}</strong></div></div><p class="sub">Prototype early-warning estimate based on academic indicators.</p><p class="dash-note">For academic planning, not a final outcome.</p><button data-view="academic">View Academic Health</button>`}
function dashboardEvidenceSummary(){let parsed=state.resume?.parsed,skills=parsed?.skills?.length||0,projects=(parsed?.projects?.length||0)+(state.student.projects||[]).length,weekly=state.learning?.lastQuiz,links=parsed?.links?.length||0;return `<div class="dash-mini-grid evidence"><div><span>Resume</span><strong>${parsed?'Uploaded':'Not uploaded'}</strong></div>${parsed?`<div><span>Skills detected</span><strong>${skills}</strong></div>`:''}${projects?`<div><span>Project evidence signals</span><strong>${projects}</strong></div>`:''}${links?`<div><span>Verified links</span><strong>${links}</strong></div>`:''}<div><span>Weekly check</span><strong>${weekly?Math.round(weekly.score)+'%':'Pending'}</strong></div></div><button data-view="profile">View evidence</button>`}
function dashboardCompanyAccess(cs){return cs.slice(0,4).map(c=>{let e=eligibility(c),detail=e[2]||{};return `<div class="row compact-company"><span class="dot"></span><div class="row-main"><strong>${esc(c.name)}</strong><small>${esc(e[0])}${Number.isFinite(detail.profileFit)?` - ${detail.profileFit}% profile fit`:''}</small></div>${pill(e[0])}</div>`}).join('')||'<p class="sub">Choose a target role to view relevant company access.</p>'}
function dashboardGapRows(gs){return gs.slice(0,5).map(g=>{let ev=getSkillEvidence(g.name,role()),pct=g.need?Math.min(100,Math.round(ev.evidenceScore/g.need*100)):0;return `<div class="dash-gap"><div class="gap-top"><span><strong>${esc(g.name)}</strong></span><em>${esc(ev.status)}</em></div><div class="dash-gap-score">${ev.evidenceScore} evidence / ${g.need} required</div><div class="bar" aria-label="${esc(g.name)} evidence score compared with role requirement"><i style="width:${pct}%"></i></div><small>${g.gap}-point evidence gap - ${esc(ev.evidenceConfidence)} confidence</small></div>`}).join('')||'<p class="sub">Your current evidence covers the selected role requirements.</p>'}
function dashboardWhatIfPreview(topGap){if(!topGap)return '<p class="sub">No open skill gap is available for a simulation preview.</p>';let r=role(),beforeSkill=getSkillEvidence(topGap.name,r),copy=structuredClone(state.student);copy.skills={...(copy.skills||{}),[topGap.name]:topGap.need};let afterSkill=getSkillEvidence(topGap.name,r,copy),beforeRole=roleScore(r),afterRole=roleScore(r,copy),beforeReady=readiness(r),afterReady=readiness(r,copy),afterGap=Math.max(0,afterSkill.roleRequirement-afterSkill.evidenceScore);return `<div class="dash-sim-title">What if you strengthen ${esc(topGap.name)}?</div><div class="dash-sim-grid"><div><span>Current</span><strong>${beforeRole}%</strong><small>Compatibility</small></div><div><span>Simulated</span><strong>${afterRole}%</strong><small>Compatibility</small></div><div><span>Readiness</span><strong>${beforeReady} -> ${afterReady}</strong><small>Preparedness</small></div><div><span>Gap</span><strong>${beforeSkill.gap} -> ${afterGap}</strong><small>Evidence points</small></div></div><p class="sub">Simulation only. The saved profile is unchanged.</p><button data-view="simulator">Explore What-if Lab</button>`}
function dashboardRecentProgressCompact(){let snaps=state.student.snapshots||[],last=snaps.at(-1),prev=snaps.length>1?snaps.at(-2):null,quiz=state.learning?.lastQuiz,parsed=state.resume?.parsed,items=[];if(prev&&last&&last.score!==prev.score)items.push(`Readiness changed from ${prev.score} to ${last.score}.`);else items.push('No readiness change since your last saved check.');if(quiz)items.push(`Latest weekly check: ${Math.round(quiz.score)}% across ${(quiz.skills||[]).join(', ')||'tracked skills'}.`);if(parsed)items.push(`Resume evidence contains ${parsed.skills?.length||0} detected technical skills.`);return `<ul class="dash-progress-list">${items.slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`}
dashboard=function(){if(!state.student.target)return layout(`<section class="dashboard-command"><section class="dash-cards"><article class="card readiness dash-readiness"><div class="label">Placement readiness</div><div class="value" style="font-size:22px;letter-spacing:0">Not assessed</div><div class="sub">Choose a target role to activate career analysis.</div></article><article class="card dash-metric"><div class="label">Role compatibility</div><h2>No target role</h2><p class="sub">Role compatibility starts once your goal is selected.</p><button class="primary" data-nav="roles">Choose target role</button></article><article class="card dash-metric"><div class="label">Profile evidence</div>${dashboardEvidenceSummary()}</article><article class="card dash-metric"><div class="label">Academic health</div>${dashboardAcademicSummary()}</article></section><section class="dash-main-grid"><article class="card action dash-next"><div class="label">Start here</div><h2>Pick the role you want to build toward.</h2><p>ASCENTRA will then summarize your evidence, gaps, roadmap priorities, company access, and simulations from one canonical intelligence layer.</p><button class="primary" data-nav="roles">Explore roles</button></article><article class="card dash-ai-card"><div class="label">ASCENTRA AI</div><h2>Need help choosing?</h2><p>Ask the copilot to compare paths using your saved profile context.</p><button data-dashboard-ai="Help me choose a target role">Ask ASCENTRA AI</button></article></section></section>`);let r=role(),parts=readinessParts(r),rs=roleScore(r),gs=gaps(r),top=gs[0],cs=relevantCompanies(r),eligible=cs.filter(c=>eligibility(c)[0]==='ELIGIBLE'),near=cs.filter(c=>eligibility(c)[0]==='NEAR ELIGIBILITY'),build=cs.length-eligible.length-near.length;return layout(`<section class="dashboard-command"><section class="dash-cards"><article class="card readiness dash-readiness"><div class="label">Placement readiness</div><div class="value">${parts.total}<small>/100</small></div><div class="sub">Preparedness, not placement probability</div>${readinessExplain()}</article><article class="card dash-metric"><div class="label">Role compatibility</div><h2>${esc(r.name)}</h2><div class="metric-number">${rs}%</div><p class="sub">Compatibility from centralized skill evidence.</p><button data-nav="roles">Change goal</button></article><article class="card dash-metric"><div class="label">Opportunity access</div><h2>${eligible.length} ready</h2><div class="dash-countline">${near.length} near eligibility - ${Math.max(0,build)} to build toward</div><p class="sub">Campus alignment: ${campus(r)}%</p><button data-view="companies">Explore companies</button></article><article class="card dash-metric"><div class="label">Academic health</div>${dashboardAcademicSummary()}</article></section><section class="dash-main-grid"><article class="card action dash-next"><div class="label">Next best action</div><h2>${top?esc(top.name):'Maintain your momentum'}</h2>${top?`<p>${esc(top.name)} is currently your largest evidence gap for ${esc(r.name)}.</p><div class="dash-evidence-line"><strong>${top.current}</strong><span>evidence / ${top.need} required</span><em>${top.gap}-point gap</em></div>`:'<p>Your selected-role requirements are currently covered. Keep evidence current through projects and weekly checks.</p>'}<div class="chips"><button class="primary" data-view="roadmap">Start roadmap</button><button data-view="simulator">Simulate improvement</button></div></article><article class="card dash-company"><div class="section-head"><h2>Relevant opportunities</h2><button data-view="companies">Explore</button></div>${dashboardCompanyAccess(cs)}</article></section><section class="card dash-gaps"><div class="section-head"><div><div class="label">Priority skill gaps</div><h2>What is holding you back</h2></div><button data-view="constellation">Open Constellation</button></div>${dashboardGapRows(gs)}</section><section class="dash-secondary-grid"><article class="card dash-whatif"><div class="label">What-if preview</div>${dashboardWhatIfPreview(top)}</article><article class="card dash-ai-card"><div class="label">ASCENTRA AI</div><h2>Career & Academic Copilot</h2><p>Ask for an explanation of your live profile, gaps, readiness, companies, or academic signal.</p><div class="chips"><button data-dashboard-ai="Explain my readiness">Explain readiness</button><button data-dashboard-ai="${top?`Why is ${top.name} my priority?`:'What should I focus on this week?'}">${top?`Why ${esc(top.name)}?`:'Weekly focus'}</button><button class="primary" data-view="guide">Ask ASCENTRA AI</button></div></article></section><section class="dash-secondary-grid"><article class="card dash-evidence"><div class="section-head"><div><div class="label">Profile evidence</div><h2>Evidence status</h2></div></div>${dashboardEvidenceSummary()}</article><article class="card recent-progress dash-progress"><div class="label">Recent progress</div><h2>Latest signals</h2>${dashboardRecentProgressCompact()}</article></section></section>`)}
document.addEventListener('click',e=>{let ai=e.target.closest('[data-dashboard-ai],[data-profile-ai]');if(!ai)return;e.preventDefault();e.stopImmediatePropagation();let prompt=ai.dataset.dashboardAi||ai.dataset.profileAi||'';view='guide';render();let input=document.querySelector('#guide-input');if(input){input.value=prompt;input.focus()}},true);
function sortedRoles(list=roles){let target=state.student.target;return [...list].sort((a,b)=>(a.id===target?-1:b.id===target?1:roleScore(b)-roleScore(a)))}
function roleEvidenceList(r){return Object.keys(r.req).map(skill=>getSkillEvidence(skill,r)).sort((a,b)=>b.evidenceScore-a.evidenceScore)}
function strongEvidenceForRole(r){let nonResumeOnly=ev=>!ev.meaningfulEvidence?.length||ev.meaningfulEvidence.some(x=>x!=='resume'&&x!=='roadmap');let strong=roleEvidenceList(r).filter(ev=>ev.evidenceScore>0&&ev.evidenceScore>=ev.roleRequirement*.75&&nonResumeOnly(ev)).slice(0,3);if(strong.length)return strong;return roleEvidenceList(r).filter(ev=>ev.evidenceScore>0&&nonResumeOnly(ev)).slice(0,3)}
function roleTopGap(r){return gaps(r)[0]||null}
function roleInsight(){if(!state.student.target)return '<p class="role-insight muted">Choose a role to make it your primary career goal.</p>';let current=role(),currentScore=roleScore(current),best=sortedRoles(roles).find(r=>r.id!==current.id&&roleScore(r)>currentScore);return best?`<p class="role-insight">Your strongest current evidence alignment is <strong>${esc(best.name)} (${roleScore(best)}%)</strong>. Your selected goal is <strong>${esc(current.name)} (${currentScore}%)</strong>.</p>`:''}
function roleEvidenceChips(items,empty='No strong role-relevant evidence yet'){return items.length?items.map(ev=>`<span>${esc(ev.skill)}</span>`).join(''):`<em>${esc(empty)}</em>`}
function evidenceProvenance(ev){let s=ev.sources||{},parts=[];if(s.project?.available)parts.push(s.project.quality==='applied'?'Project evidence':'Project mention');if(s.assessment?.available)parts.push(s.assessment.quality==='per_skill'?'Weekly assessment':'Shared weekly check');if(s.profile?.available)parts.push('Profile evidence');if(s.resume?.available)parts.push(s.resume.quality==='contextual'?'Resume context':'Resume mention');if(s.roadmap?.available)parts.push('Roadmap progress');return parts.length?parts.join(' + '):'No validated evidence'}
function roleEvidenceRows(items,empty){return items.length?`<ul class="role-evidence-list">${items.map(ev=>`<li><div><strong>${esc(ev.skill)}</strong><span>${ev.evidenceScore} evidence / ${ev.roleRequirement} required</span></div><small>${esc(ev.status)} - ${esc(evidenceProvenance(ev))} - ${esc(ev.evidenceConfidence)} confidence</small></li>`).join('')}</ul>`:`<p class="sub">${esc(empty)}</p>`}
function roleDetailModal(r){let evs=roleEvidenceList(r),strong=strongEvidenceForRole(r),needs=evs.filter(ev=>ev.gap>0).sort((a,b)=>b.gap-a.gap).slice(0,3),priority=roleTopGap(r),isTarget=r.id===state.student.target;modal(`<div class="role-detail"><div class="role-card-top"><div><div class="label">${esc(r.cat)}</div><h2>${esc(r.name)}</h2></div>${isTarget?'<span class="target-badge">CURRENT TARGET</span>':''}</div><p class="sub">${esc(r.desc)}</p><div class="role-detail-metrics"><div><span>Compatibility</span><strong>${roleScore(r)}%</strong></div><div><span>Campus alignment</span><strong>${campus(r)}%</strong></div></div><section><h3>Strongest evidence</h3>${roleEvidenceRows(strong,'No strong saved evidence is mapped to this role yet.')}</section><section><h3>Top gaps</h3>${roleEvidenceRows(needs,'Core requirements are currently covered.')}</section><section class="role-priority"><div class="label">BIGGEST PRIORITY</div>${priority?`<h3>${esc(priority.name)}</h3><p><strong>${priority.gap}-point evidence gap</strong></p><p>Strengthening evidence for ${esc(priority.name)} would address your largest current ${esc(r.name)} gap.</p>`:'<p class="sub">Core requirements are currently covered.</p>'}</section><p class="sub">Campus alignment reflects ASCENTRA's configured campus opportunity data and is separate from role compatibility.</p><footer><button data-role-target="${r.id}" class="${isTarget?'lime':''}">${isTarget?'Primary goal':'Set goal'}</button><button data-role-compare="${r.id}">${compare.includes(r.id)?'Selected for compare':'Compare'}</button><button data-role-ai="Why does ${esc(r.name)} match my current evidence?">Ask ASCENTRA AI</button><button class="close-modal">Close</button></footer></div>`)}
function roleCards(list){let ordered=sortedRoles(list);return ordered.length?ordered.map(r=>{let isTarget=r.id===state.student.target,score=roleScore(r);return `<article class="card entity role-card refined"><div class="role-card-top"><div><div class="label">${esc(r.cat)}</div><h3>${esc(r.name)}</h3></div>${isTarget?'<span class="target-badge">CURRENT TARGET</span>':''}</div><p>${esc(r.desc)}</p><div class="role-stat-grid"><div><span>Compatibility</span><strong>${score}%</strong></div><div><span>Campus alignment ${info("Campus alignment","Campus alignment reflects how strongly this role connects with ASCENTRA's configured campus opportunity data. It is separate from role compatibility.")}</span><strong>${campus(r)}%</strong></div></div><button type="button" class="role-detail-trigger" data-role-detail="${r.id}">Why this role?</button><footer><button data-target="${r.id}" class="${isTarget?'lime':''}">${isTarget?'Primary goal':'Set goal'}</button><button data-compare="${r.id}">${compare.includes(r.id)?'Selected':'Compare'}</button></footer></article>`}).join(''):'<article class="card"><p>No roles match your search.</p><p class="sub">Try another title, category, or description keyword.</p></article>'}
function rolesPage(){let ordered=sortedRoles(roles);return layout(`<div class="page-head role-page-head"><h1>Explore career roles.</h1><p>Role compatibility compares your current skill evidence with the requirements of each role. Campus alignment is shown separately from ASCENTRA's configured opportunity data.</p>${roleInsight()}</div><div class="filters"><input id="role-search" placeholder="Search roles"><select id="role-cat"><option value="">All categories</option>${[...new Set(roles.map(r=>r.cat))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><button id="compare-open">Compare selected (${compare.length}/3)</button></div><div class="cards role-cards" id="role-cards">${roleCards(ordered)}</div>`)}
function filterRoles(){let q=document.querySelector('#role-search').value.toLowerCase(),cat=document.querySelector('#role-cat').value,list=roles.filter(r=>(!q||r.name.toLowerCase().includes(q)||r.cat.toLowerCase().includes(q)||String(r.desc||'').toLowerCase().includes(q))&&(!cat||r.cat===cat));document.querySelector('#role-cards').innerHTML=roleCards(list);document.querySelectorAll('#role-cards [data-target]').forEach(b=>b.onclick=()=>{state.student.target=b.dataset.target;record();toast(`Primary goal set: ${role().name}`);render()});document.querySelectorAll('#role-cards [data-compare]').forEach(b=>b.onclick=()=>{let id=b.dataset.compare;compare=compare.includes(id)?compare.filter(x=>x!==id):compare.length<3?[...compare,id]:compare;render()});let btn=document.querySelector('#compare-open');if(btn)btn.textContent=`Compare selected (${compare.length}/3)`}
function compareRolePanel(r){let strong=strongEvidenceForRole(r),gap=roleTopGap(r),evs=roleEvidenceList(r),ready=evs.filter(ev=>ev.status==='Ready').length,developing=evs.filter(ev=>ev.status==='Developing').length,priority=evs.filter(ev=>ev.status==='Priority gap').length;return `<article class="card compare-role-card"><div class="label">${esc(r.cat)}</div><h3>${esc(r.name)}</h3><div class="compare-stat"><span>Compatibility</span><strong>${roleScore(r)}%</strong></div><div class="compare-stat"><span>Campus alignment</span><strong>${campus(r)}%</strong></div><div class="compare-mini"><span>Strong evidence</span><p>${roleEvidenceChips(strong)}</p></div><div class="compare-mini"><span>Largest gap</span><p>${gap?`${esc(gap.name)} ${gap.gap}`:'Core requirements covered'}</p></div><div class="compare-statuses"><span>Ready ${ready}</span><span>Developing ${developing}</span><span>Priority gaps ${priority}</span></div><button data-target="${r.id}">${r.id===state.student.target?'Primary goal':'Set primary goal'}</button></article>`}
function compareRequirementRows(rs){let skills=[...new Set(rs.flatMap(r=>Object.keys(r.req)))].sort((a,b)=>Math.max(...rs.map(r=>r.req[b]||0))-Math.max(...rs.map(r=>r.req[a]||0)));return skills.map(skill=>{let evidence=Math.max(...rs.map(r=>getSkillEvidence(skill,r).evidenceScore));return `<tr><th>${esc(skill)}</th><td class="compare-evidence">${evidence}</td>${rs.map(r=>{let req=r.req[skill];if(!req)return '<td class="req-cell not-required"><span>Not required</span></td>';let ev=getSkillEvidence(skill,r),met=ev.evidenceScore>=req;return `<td class="req-cell ${met?'req-met':'req-gap'}"><strong>${req}</strong><small>${met?'Satisfied':'Open gap'}</small></td>`}).join('')}</tr>`}).join('')}
function sharedSkillOpportunity(rs){if(rs.length<2)return '';let shared=[...new Set(rs.flatMap(r=>gaps(r).map(g=>g.name)))].filter(skill=>rs.every(r=>Object.hasOwn(r.req,skill)&&gaps(r).some(g=>g.name===skill))).sort((a,b)=>Math.max(...rs.map(r=>getSkillEvidence(b,r).gap))-Math.max(...rs.map(r=>getSkillEvidence(a,r).gap))),scope=rs.length===2?'both selected roles':'all three selected roles';return shared[0]?`<p class="compare-insight"><strong>Shared opportunity:</strong> Strengthening ${esc(shared[0])} would improve your evidence alignment across ${scope}.</p>`:''}
function openCompare(){if(compare.length<2)return toast('Select two or three roles to compare.');let rs=compare.map(id=>roles.find(r=>r.id===id)).filter(Boolean);modal(`<h2>Role comparison</h2><p class="sub">Comparison uses role compatibility, campus alignment, and skill evidence from ASCENTRA Core. It is not a placement probability.</p>${sharedSkillOpportunity(rs)}<div class="compare-grid refined">${rs.map(compareRolePanel).join('')}</div><div class="compare-table-wrap"><table class="compare-table"><thead><tr><th>Skill</th><th>Evidence</th>${rs.map(r=>`<th>${esc(r.name)} req</th>`).join('')}</tr></thead><tbody>${compareRequirementRows(rs)}</tbody></table></div><button class="close-modal">Close</button>`);document.querySelectorAll('.modal [data-target]').forEach(b=>b.onclick=()=>{state.student.target=b.dataset.target;record();closeModal();render()})}
document.addEventListener('click',e=>{let ai=e.target.closest('[data-role-ai]');if(!ai)return;e.preventDefault();e.stopImmediatePropagation();closeModal();view='guide';render();let input=document.querySelector('#guide-input');if(input){input.value=ai.dataset.roleAi;input.focus()}},true);
document.addEventListener('click',e=>{let detail=e.target.closest('[data-role-detail]');if(!detail)return;e.preventDefault();e.stopImmediatePropagation();let r=roles.find(x=>x.id===detail.dataset.roleDetail);if(r)roleDetailModal(r)},true);
document.addEventListener('click',e=>{let target=e.target.closest('[data-role-target]');if(!target)return;e.preventDefault();e.stopImmediatePropagation();state.student.target=target.dataset.roleTarget;record();closeModal();toast(`Primary goal set: ${role().name}`);render()},true);
document.addEventListener('click',e=>{let btn=e.target.closest('[data-role-compare]');if(!btn)return;e.preventDefault();e.stopImmediatePropagation();let id=btn.dataset.roleCompare;compare=compare.includes(id)?compare.filter(x=>x!==id):compare.length<3?[...compare,id]:compare;closeModal();render()},true);
function settingValueText(id,value){return id==='font'||id==='contrast'?`${value}%`:String(value)}
function safeStudentRecord(){return JSON.parse(JSON.stringify(state.student||{},(key,value)=>/photoData/i.test(key)?'[redacted profile photo data]':/(password|token|api.?key|secret|cookie)/i.test(key)?'[redacted]':value))}
function clearConversationHistory(){state.guideHistory=[];if(state.profileGuide)state.profileGuide={...state.profileGuide,messages:[]};if(state.onboarding)state.onboarding={...state.onboarding,messages:[]};window._ascentraLastPrompt='';save()}
function resetBrowserStateForLogout(){Store.saveDeviceSettings(state.settings);state=hydrateAccountState(null,null,{fresh:true});compare=[];lastSimulation=null;window._ascentraLastPrompt=''}
async function logoutUser(){try{await fetch('/api/logout',{method:'POST',credentials:'include'})}catch{}resetBrowserStateForLogout();account=null;appMode='login';render()}
async function deleteAccountAndSyncedData(){let id=account?.id;try{await fetch('/api/account',{method:'DELETE',credentials:'include'})}catch{}if(id)localStorage.removeItem(Store.key(id));localStorage.removeItem('ascentra');state=hydrateAccountState(null,null,{fresh:true});compare=[];lastSimulation=null;window._ascentraLastPrompt='';account=null;appMode='login';render()}
function confirmDeleteAccount(){modal(`<div class="label danger-label">DANGER ZONE</div><h2>Delete account and synced data?</h2><p>This permanently deletes your ASCENTRA account and the profile stored by this application. External service data, if any, may not be covered.</p><div class="settings-danger-actions"><button class="close-modal">Cancel</button><button class="danger" data-confirm-delete-account>Delete account</button></div>`)}
settingsPage=function(){let s=state.settings;return layout(`<div class="page-head settings-page-head"><h1>Make Ascentra yours.</h1><p>Interface preferences apply immediately. Account sync and memory settings control what is saved.</p></div><div class="grid two settings-grid"><article class="card settings-card"><h2>Appearance</h2><div class="chips appearance-modes" aria-label="Appearance mode">${['light','dark','system'].map(x=>`<button data-set-theme="${x}" class="${s.theme===x?'lime':''}" aria-pressed="${s.theme===x?'true':'false'}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><label>Accent color <input id="accent" type="color" value="${esc(s.accent)}"></label><label>Interface contrast <span class="setting-value" data-setting-value="contrast">${esc(settingValueText('contrast',s.contrast))}</span><input id="contrast" type="range" min="70" max="130" value="${esc(s.contrast)}"></label></article><article class="card settings-card"><h2>Accessibility & interface</h2><label>Font size <span class="setting-value" data-setting-value="font">${esc(settingValueText('font',s.font))}</span><input id="font" type="range" min="85" max="125" value="${esc(s.font)}"></label><label class="check"><input id="motion" type="checkbox" ${s.motion?'checked':''}> Enable interface motion</label><label>Density <select id="density"><option value="comfortable" ${s.density==='comfortable'?'selected':''}>Comfortable</option><option value="compact" ${s.density==='compact'?'selected':''}>Compact</option></select></label><p class="sub">Your OS reduced-motion preference takes precedence over ASCENTRA motion settings.</p></article></div>`)}
accountControls=function(){let w=document.createElement('article'),s=state.settings;w.className='card settings-account-card';w.innerHTML=`<h2>Account & data</h2><p class="sub">Login persistence is controlled by Remember me. Profile sync and conversation memory are managed separately below.</p><section class="settings-group"><div><div class="label">MEMORY / SYNC</div><label class="check"><input id="remember-profile" type="checkbox" ${s.rememberProfile!==false?'checked':''}> Sync my career profile to my account</label><p class="sub">Your profile remains available on this browser. Turning this off stops future account sync until you enable it again.</p><label class="check"><input id="remember-conversations" type="checkbox" ${s.rememberConversations!==false?'checked':''}> Remember ASCENTRA AI conversations</label><p class="sub">Turning this off keeps the current conversation available during this session but prevents conversation history from being saved.</p></div></section><section class="settings-group"><div class="label">DATA</div><div class="chips"><button id="view-data">View current student record</button><button id="export-data">Download my data</button></div><p class="sub">Export may include profile information, resume text, academic results, roadmap history, settings, and saved ASCENTRA AI conversations. Downloads your account-synced data; browser-only changes may not be included while profile sync is off.</p></section><section class="settings-group"><div class="label">ACCOUNT</div><div class="chips"><button id="rerun-onboarding">Re-run onboarding</button><button id="logout">Log out</button></div><p class="sub">Re-run onboarding restarts guidance without deleting your saved profile or evidence.</p></section><section class="settings-group danger-zone"><div class="label">DANGER ZONE</div><div class="chips"><button id="clear-conversations" class="warning-action">Delete conversations</button><button id="delete-account" class="danger">Delete account and synced data</button></div></section>`;document.querySelector('.main').append(w);document.querySelector('#remember-profile').onchange=e=>{state.settings.rememberProfile=e.target.checked;save()};document.querySelector('#remember-conversations').onchange=e=>{state.settings.rememberConversations=e.target.checked;save()};document.querySelector('#view-data').onclick=()=>modal(`<h2>Current student record</h2><pre style="white-space:pre-wrap;font-size:11px">${esc(JSON.stringify(safeStudentRecord(),null,2))}</pre><button class="close-modal">Close</button>`);document.querySelector('#export-data').onclick=async()=>{let d=await (await fetch('/api/export',{credentials:'include'})).json(),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='ascentra-profile.json';a.click();URL.revokeObjectURL(a.href)};document.querySelector('#clear-conversations').onclick=()=>{clearConversationHistory();toast('ASCENTRA AI conversations deleted.')};document.querySelector('#rerun-onboarding').onclick=()=>{state.onboarding={step:0,messages:[],complete:false};save();appMode='onboarding';render()};document.querySelector('#logout').onclick=logoutUser;document.querySelector('#delete-account').onclick=confirmDeleteAccount}
function applySettings(){let s=state.settings,osReduced=matchMedia('(prefers-reduced-motion: reduce)').matches,dark=s.theme==='dark'||(s.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches),accent=s.accent||'#c6f260';document.body.classList.toggle('dark',dark);document.body.classList.toggle('no-motion',!s.motion||osReduced);document.documentElement.style.setProperty('--lime',accent);document.body.style.setProperty('--lime',accent);document.documentElement.style.fontSize=(s.font||100)+'%';document.body.style.filter=`contrast(${s.contrast||100}%)`;document.body.classList.toggle('compact',s.density==='compact')}
function setupSystemThemeListener(){let mq=matchMedia('(prefers-color-scheme: dark)');mq.addEventListener?.('change',()=>{if(state.settings.theme==='system'){applySettings();render()}})}
document.addEventListener('input',e=>{let id=e.target?.id;if(!['font','contrast'].includes(id))return;let el=document.querySelector(`[data-setting-value="${id}"]`);if(el)el.textContent=settingValueText(id,e.target.value)},true);
document.addEventListener('change',e=>{let id=e.target?.id;if(id==='motion'||id==='density'){state.settings[id]=id==='motion'?e.target.checked:e.target.value;save();applySettings()}},true);
document.addEventListener('click',e=>{let b=e.target.closest?.('[data-confirm-delete-account]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();deleteAccountAndSyncedData()},true);
function boot(){setupSystemThemeListener();appMode='login';render()}
boot();
